 for(let side of [-1,1])catOval(side*13,-11,4.7,13,'#a45630','#79482e');catFace({fur:'#e5bb87',cream:'#ffedd2',eye:'#5f944f',wide:16});
 catShape('M -15 -23 Q -16 -34 -2 -31 Q 11 -34 15 -22 Q 8 -27 0 -21 L 0 -27 Q -8 -20 -15 -23 Z','#b86433','#79482e');line([[-10,-28],[-3,-30],[6,-28]],'#e2a063',1.3);catOval(2,-32,5.3,4.3,'#a6552e','#79482e');line([[-1,-33],[3,-35],[5,-32]],'#d9884e',1);
 line([[-10,-1],[0,3],[10,-1]],'#cf8c91',4);line([[5,2],[7,10]],'#df9fa0',3);ellipse(0,8,3,3,'#f6d3a1');for(let side of [-1,1])ellipse(side*1.2,7,.7,1,'#3c4138');
