// Reward presentation only: no damage, enemy, input or save state lives here.
function rewardCardLabel(offer){
 if(offer.total)return offer.path.toUpperCase()+' · STEP '+offer.rank+' OF '+offer.total+(offer.rank===offer.total?' · FINAL UPGRADE':'');
 let rarity=RARITIES[offer.rarity];return rarity.symbol+' '+rarity.name.toUpperCase()+' · '+offer.path.toUpperCase();
}
function rewardCardHint(offer){
 if(!offer.total)return '';
 return '<em class="rewardHint">'+(offer.rank===offer.total?'COMPLETE THIS ABILITY':offer.total-offer.rank+' further steps to master')+'</em>';
}
function clearRewardNotice(){let el=$('rewardToast');el.classList.remove('rewardShow');el.style.display='none';}
function rewardNotice(title,detail,color){
 let el=$('rewardToast');el.style.setProperty('--reward-color',color);el.firstChild.textContent=title;
 // Separate text nodes keep all reward wording literal and accessible.
 $('rewardToastDetail').textContent=detail;el.style.display='block';el.classList.remove('rewardShow');void el.offsetWidth;el.classList.add('rewardShow');
 rewardChime(color===RARITIES[4].color);
}
function celebrateReward(offer){
 let title=offer.total?(offer.rank===offer.total?'ABILITY MASTERED':'ABILITY UPGRADED'):RARITIES[offer.rarity].name.toUpperCase()+' POWER';
 rewardNotice(title,offer.name+' · '+(offer.path==='stat'?offer.text:offer.total?'Step '+offer.rank+' of '+offer.total:offer.text),RARITIES[offer.rarity].color);
}
function charmRewardHint(key){
 let copies=[...run.charms,...run.charmBag].filter(c=>c.key===key&&c.rank===1).length;
 if(copies)return 'MATCHING COPY · FUSE IN TOWN';
 if(charmRank(key))return 'BAG COPY · KEEP FOR FUSION';
 if(run.charms.length>=3)return 'BAG · EQUIP OR SWAP IN TOWN';
 if((key==='opportunist'&&charmRank('frost'))||(key==='frost'&&charmRank('opportunist'))||(key==='heavy'&&charmRank('keen'))||(key==='keen'&&charmRank('heavy')))return 'BUILD COMBO · EQUIPS NOW';
 return 'EQUIPS NOW';
}
function rewardChime(legendary=false){
 try{
  let Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
  let audio=rewardChime.audio||(rewardChime.audio=new Audio());
  const play=()=>{if(audio.state!=='running')return;let at=audio.currentTime;for(let [i,note] of (legendary?[523,659,784,1047]:[440,554,659]).entries()){
   let tone=audio.createOscillator(),gain=audio.createGain(),start=at+i*.065;tone.type='sine';tone.frequency.value=note;
   gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.025,start+.012);gain.gain.exponentialRampToValueAtTime(.001,start+.20);
   tone.connect(gain);gain.connect(audio.destination);tone.start(start);tone.stop(start+.21);
  }};
  if(audio.state==='suspended')audio.resume().then(play).catch(()=>{});else play();
 }catch{}
}

// Shared run progression: six choices per arena; five areas to complete a run.
function effectiveStats(){let b=CHARACTERS[selected],s=buildStats();return {...b,hp:s.health,speed:b.speed*(1+s.speed/100)*(1+activePermanentBonus('speed')/100)*(state!=='menu'&&run.shopBought?.includes('speed')?1.05:1)*(shrineBuff?.kind==='speed'&&shrineBuff.left>0?1.15:1),rate:b.rate*normalRate(),dodgeSpeed:b.dodgeSpeed*(D(1)?selected==='jackson'?1.3:1.15:1)};}
function normalRate(){return 1/attackSpeedFactor();}
function damageScale(source){if(!['weapon','cat'].includes(source))return 1;return permanentWeaponScale(source)*(1+buildStats().power/100)*(run.shopBought?.includes('power')?1.1:1);}
function specialCooldown(){let base=isHavannah()&&S(4)?10:CHARACTERS[selected].specialCD;return (S(4)&&!isMimi()&&!isJoseph()&&!isTom()&&!isHavannah()?({jackson:7,ava:7,stef:8,jodie:9,evie:8,zak:9}[selected]):base)*(1-buildStats().special/100)*charmSpecialFactor()*(1-activePermanentBonus('cooldown')/100);}
function dodgeCooldown(){if(isHavannah())return 1.9*(D(3)?.8:1)*(1-buildStats().dodge/100);if(isTom())return 2.4*(D(3)?.8:1)*(1-buildStats().dodge/100);if(isJoseph())return 1.8*(D(3)?.8:1)*(1-buildStats().dodge/100);return (isStef()?(D(4)?2.3:3):(D(4)?selected==='jackson'?1.05:1.25:1.65))*(1-buildStats().dodge/100);}
function resetProgression(){clearRewardNotice();shrine=null;shrineBuff=null;hearts=[];nextHeartAt=0;run={visited:[],level:1,stage:0,stagePicks:0,special:0,dodge:0,stat:new Set(),stats:{},statLegendary:{},earned:0,offers:[],history:[],firstArena:arenaKey,perk:null,rewardOffers:null,shopBought:[],shopRerolls:0,shopStock:null,goldEarned:0};run.permanent={...progress.heroes[selected]};run.journeyId=newJourneyId();run.essenceAwards=[];run.essenceEarned=0;run.started=false;hazards=[];scheduled=[];decoy=null;goldDrops=[];resetPark();resetCharms();}
function nextXP(){return 12+run.stagePicks*5;}
function weaponData(){return isHavannah()?[havNames,havText]:isTom()?[tomNames,tomText]:isJoseph()?[josephNames,josephText]:isMimi()?[mimiNames,mimiText]:isZak()?[zakNames,zakText]:isEvie()?[evieNames,evieText]:isJodie()?[jodieNames,jodieText]:isStef()?[stefNames,stefText]:isAva()?[avaNames,avaText]:[upgradeNames,upgradeText];}


// Choices 3 and 6 in each arena are milestones, with a Rare-or-better stat.
function upgradeRarityFloor(){return (run.stagePicks+1)%3===0?(run.stage>=3?3:2):0;}
function rewardStatAvailable(key){return statAvailable(key)&&!(charmRank('blunt')&&['precision','ferocity'].includes(key))&&!(run.charmFX?.lanternUsed&&['regen','restoration'].includes(key));}
function makeStatOffer(exclude=new Set()){let keys=Object.keys(STAT_TRACKS).filter(k=>rewardStatAvailable(k)&&!exclude.has(k));if(!keys.length)return null;let key=keys[Math.min(keys.length-1,Math.floor(rewardRandom()*keys.length))],rarity=rollRarity(upgradeRarityFloor()),d=STAT_TRACKS[key],gain=statGain(key,rarity);return {path:'stat',index:key,name:d.name,rarity,rank:rarity+1,icon:d.icon,text:'+'+(Math.round(gain*100)/100)+d.unit+' · '+(Math.round(statValue(key)*100)/100)+d.unit+' → '+(Math.round((statValue(key)+gain)*100)/100)+d.unit};}
function buildOffers(){let abilities=[];if(tier<maxTier()){let [names,texts]=weaponData(),rarity=Math.min(4,tier+(isStef()||isEvie()?1:0));abilities.push({path:'weapon',index:tier,name:names[tier],text:texts[tier],rarity,rank:tier+1,total:maxTier(),icon:'⚔'});}if(run.special<5){let [name,text]=SPECIALS[selected][run.special];abilities.push({path:'special',index:run.special,name,text,rarity:run.special,rank:run.special+1,total:5,icon:'✦'});}if(run.dodge<5){let [name,text]=DODGES[selected][run.dodge];abilities.push({path:'dodge',index:run.dodge,name,text,rarity:run.dodge,rank:run.dodge+1,total:5,icon:'↪'});}let offers=[];if(abilities.length)offers.push(abilities.splice(run.history.length%abilities.length,1)[0]);let stat=makeStatOffer();if(stat)offers.push(stat);if(abilities.length)offers.push(abilities[run.history.length%abilities.length]);while(offers.length<3){let more=makeStatOffer(new Set(offers.filter(o=>o.path==='stat').map(o=>o.index)));if(more){offers.push(more);continue;}if(p.hp<stats().hp&&!offers.some(o=>o.path==='recovery'))offers.push({path:'recovery',name:'Field Recovery',text:'Restore 25% maximum health.',rarity:1,icon:'♥'});else offers.push({path:'refresh',name:'Catch Your Breath',text:'Recharge special and dodge.',rarity:0,icon:'◷'});}return offers.slice(0,3);}
function showUpgrade(force=false){if(state!=='playing'||run.stagePicks>=UPGRADES_PER_ARENA||run.earned<nextXP()||(!force&&time<(run.stagePicks===0?8:LEVEL_TIMES[run.stagePicks]-3)))return;clearRewardNotice();state='upgrade';run.offers=buildOffers();$('runSummary').style.display='none';$('panel').style.display='grid';$('panelTitle').textContent=((run.stagePicks+1)%3===0?'BREAKTHROUGH':'LEVEL '+(run.level+1))+' · CHOOSE YOUR POWER';$('panelName').textContent='Make this build yours';$('panelText').textContent='Abilities change your moves. Stats amplify your build. Every third pick offers a Rare+ stat.';for(let id of ['panelButton','continue','back'])$(id).style.display='none';$('upgradeChoices').style.display='grid';$('upgradeChoices').innerHTML=run.offers.map((o,i)=>{let rarity=RARITIES[o.rarity];return '<button class="upgradeCard buildCard" data-choice="'+i+'" style="--rarity:'+rarity.color+'"><span>'+rewardCardLabel(o)+'</span><b>'+o.icon+' '+o.name+'</b><small>'+o.text+'</small>'+rewardCardHint(o)+'</button>';}).join('');for(let i=0;i<run.offers.length;i++)$('upgradeChoices').children[i].onclick=()=>chooseUpgrade(i);}
function chooseUpgrade(i){if(state!=='upgrade'||!run.offers[i])return;let o=run.offers[i],oldHP=stats().hp;run.earned=Math.max(0,run.earned-nextXP());run.stagePicks++;run.level++;if(o.path==='weapon'){tier++;p.attack=Math.min(p.attack,.12);}else if(o.path==='special')run.special++;else if(o.path==='dodge')run.dodge++;else if(o.path==='stat')addStat(o.index,o.rarity);else if(o.path==='recovery')recoverHealth(stats().hp*.25);else if(o.path==='refresh')p.chargeCD=p.dodgeCD=0;run.history.push({path:o.path,index:o.index,name:o.name,rarity:o.rarity});p.hp=Math.min(stats().hp,p.hp+(run.charmFX?.lanternUsed?0:Math.max(0,stats().hp-oldHP)));syncCats();state='playing';$('panel').style.display='none';$('upgradeChoices').style.display='none';pop(p.x,p.y,RARITIES[o.rarity].color,o.rarity===4?35:18);float(p.x,p.y-55,(o.total?'UPGRADED':RARITIES[o.rarity].name.toUpperCase())+' · '+o.name,RARITIES[o.rarity].color);celebrateReward(o);updateHud();showUpgrade();}
function progressStep(){if(run.stagePicks<UPGRADES_PER_ARENA&&time>=LEVEL_TIMES[run.stagePicks])run.earned=Math.max(run.earned,nextXP());showUpgrade();}
// Challenge follows arena order, never the reward a player just selected.
const ENCOUNTER_GROWTH=[{hp:1,damage:1},{hp:1.4,damage:1.22},{hp:1.9,damage:1.44},{hp:2.45,damage:1.67},{hp:3.1,damage:1.9}];
function enemyScale(kind){return {...ENCOUNTER_GROWTH[clamp(run.stage||0,0,4)]};}
function applyEnemyScale(e){let f=enemyScale(e.kind),old=e.scaleHP||1;e.hp*=f.hp/old;e.maxHp*=f.hp/old;e.scaleHP=f.hp;e.damageScale=f.damage;}
function scaleLivingEnemies(){for(let e of enemies)if(e.hp>0)applyEnemyScale(e);}
function arenaPaceStep(){return LEVEL_TIMES.filter(t=>time>=t).length;}
function pressureTime(){return Math.max(time*.45,arenaPaceStep()*6+(run.stage?12:0));}
function stageSpawnDelay(base){return base/(1+.045*arenaPaceStep()+(run.stage?.12:0));}
const BOSS_TIME=90,LEVEL_TIMES=[8,22,37,52,67,82];
let run={visited:[],level:1,stage:0,stagePicks:0,special:0,dodge:0,stat:new Set(),stats:{},statLegendary:{},earned:0,offers:[],history:[],firstArena:'rugby',perk:null,rewardOffers:null,shopBought:[]},hazards=[],scheduled=[],decoy=null;
const S=n=>run.special>=n,D=n=>run.dodge>=n;

// upgrades/rewards.js — source of truth.
function rewardRandom(){return rewardRolls.length?rewardRolls.shift():Math.random();}

function rollPerks(){let keys=Object.keys(PERKS);for(let i=keys.length-1;i>0;i--){let j=Math.floor(rewardRandom()*(i+1));[keys[i],keys[j]]=[keys[j],keys[i]];}return keys.slice(0,3);}

function openBossReward(){$('runSummary').style.display='none';if(state!=='won'||run.stage!==0||run.perk)return;if(!run.rewardOffers)run.rewardOffers=rollPerks();clearRewardNotice();state='perk';$('panel').style.display='grid';$('panelTitle').textContent='BOSS REWARD · CHOOSE ONE';$('panelName').textContent='Give this run a new twist';$('panelText').textContent='Three random perks. Pick one for the next arena. No rerolls.';$('panelButton').style.display='none';$('continue').style.display='none';$('back').style.display='none';$('upgradeChoices').innerHTML=run.rewardOffers.map((key,i)=>'<button class="upgradeCard perkCard" data-choice="'+i+'" style="--perk:'+PERKS[key].color+'"><span>BOSS PERK</span><b>'+PERKS[key].name+'</b><small>'+PERKS[key].text+'</small></button>').join('');$('upgradeChoices').style.display='grid';for(let i=0;i<3;i++)$('upgradeChoices').children[i].onclick=()=>chooseBossPerk(i);}

function chooseBossPerk(i){if(state!=='perk'||run.stage!==0||run.perk||!run.rewardOffers?.[i])return;run.perk=run.rewardOffers[i];run.vampBudget=2;run.lightningAt=-1;state='won';continueRun();}

function recoverHealth(amount,kind='normal'){let old=p.hp;p.hp=Math.min(stats().hp,p.hp+Math.max(0,amount)*healingFactor(kind==='blood'));let healed=p.hp-old;if(healed>.01){float(p.x,p.y-24,'+'+healed.toFixed(healed<1?1:0),'#bcf0a9');radialEffect(p.x,p.y,17,'#95ddb1');}return healed;}

function dropHeart(e){if(e.kind==='boss'||hearts.length>=6)return;let milestone=kills%12===0,low=p.hp/stats().hp<.45,chance=low?.28:.06;if(milestone||(time>=nextHeartAt&&rewardRandom()<chance)){let q=walkable(e.x,e.y,7);hearts.push({x:q.x,y:q.y,life:30,heal:Math.max(10,Math.round(stats().hp*.10))});nextHeartAt=time+2.5;}}

// Secondary perk damage scales once with Power; it still cannot proc itself.
function perkDamage(amount){return amount*(1+buildStats().power/100);}
function hitPerk(e,actual,source){if(!run.perk||actual<=0||source==='perk'||source==='status'||source==='charm'||source==='clone')return;
if(run.perk==='vampiric'){let amount=Math.min(actual*.04,(run.vampBudget||0)/Math.max(.01,healingFactor()));if(p.hp<stats().hp){let healed=recoverHealth(amount);run.vampBudget=Math.max(0,(run.vampBudget||0)-healed);}return;}
if(run.perk==='lightning'){if(time>=(run.lightningAt||-1)){let other=nearest(e,new Set([e.id]),120);if(other){run.lightningAt=time+.65;fx.push({x:e.x,y:e.y,vx:0,vy:0,life:.18,max:.18,arcX:other.x,arcY:other.y,color:'#f3e49b',r:0});damageEnemy(other,perkDamage(8),0,0,false,'perk');}}return;}
if(e.hp<=0)return;
if(run.perk==='fire'){e.burnUntil=time+2.4;if(!(e.burnNext>time))e.burnNext=time+.4;}
else if(run.perk==='ice'){e.frostUntil=time+1.2;e.slowUntil=Math.max(e.slowUntil||0,e.frostUntil);}
else if(run.perk==='wounding'){if(time>=(e.nextWound||0)){if(!(e.bleedUntil>time))e.bleedStacks=0;e.bleedStacks=Math.min(3,(e.bleedStacks||0)+1);e.nextWound=time+.2;}e.bleedUntil=time+3;if(!(e.bleedNext>time))e.bleedNext=time+.5;}}

function onDefeated(e){dropGold(e);heroicDefeated(e);charmOnKill(e);dropHeart(e);if(run.perk==='fire'&&e.burnUntil>time){let other=nearest(e,new Set([e.id]),65);if(other){other.burnUntil=Math.max(other.burnUntil||0,time+1.2);if(!(other.burnNext>time))other.burnNext=time+.4;radialEffect(other.x,other.y,13,'#efab64');}}}

function rewardStep(dt){if(run.perk==='vampiric')run.vampBudget=Math.min(2,(run.vampBudget||0)+2*dt);
for(let e of enemies){if(e.hp<=0)continue;if(e.burnUntil>time&&time>=e.burnNext){e.burnNext=time+.4;damageEnemy(e,perkDamage(2),0,0,false,'perk');}if(e.hp>0&&e.bleedUntil>time&&time>=e.bleedNext){e.bleedNext=time+.5;damageEnemy(e,perkDamage(1.5*(e.bleedStacks||1)),0,0,false,'perk');}}
for(let i=hearts.length-1;i>=0;i--){let h=hearts[i];h.life-=dt;let d=dist(h,p);if(d<52){let move=Math.min(d,150*dt);h.x+=(p.x-h.x)/(d||1)*move;h.y+=(p.y-h.y)/(d||1)*move;}if(d<17&&p.hp<stats().hp){recoverHealth(h.heal);hearts.splice(i,1);}else if(h.life<=0)hearts.splice(i,1);}}

function drawHeart(h){ctx.save();ctx.translate(h.x,h.y+Math.sin(time*4)*1.5);ellipse(0,6,7,2.2,'#173b2955');ctx.fillStyle='#e59b98';ctx.strokeStyle='#ffe1be';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(0,5);ctx.bezierCurveTo(-12,-2,-5,-10,0,-5);ctx.bezierCurveTo(5,-10,12,-2,0,5);ctx.fill();ctx.stroke();ctx.restore();}

function drawEnemyHealth(e){if(e.hp<=0||e.kind==='boss'||(e.hp>=e.maxHp&&e.kind!=='heavy'&&!e.heroic))return;let width=e.kind==='heavy'?29:21,y=e.y-e.r-18,ratio=clamp(e.hp/e.maxHp,0,1);ctx.fillStyle='#152b25dd';ctx.fillRect(e.x-width/2-1,y-1,width+2,5);ctx.fillStyle=ratio>.6?'#b6d997':ratio>.3?'#f1d17c':'#ee9380';ctx.fillRect(e.x-width/2,y,width*ratio,3);}

function drawStatus(e){if(e.hp<=0)return;if(e.burnUntil>time){ctx.strokeStyle='#efad68';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(e.x-5,e.y+3);ctx.lineTo(e.x-2,e.y-3);ctx.lineTo(e.x,e.y+2);ctx.lineTo(e.x+3,e.y-5);ctx.lineTo(e.x+5,e.y+3);ctx.stroke();}if(e.frostUntil>time){ctx.strokeStyle='#9bdcf2';ctx.lineWidth=1.4;ctx.beginPath();ctx.ellipse(e.x,e.y+e.r*.5,e.r+2,4,0,0,TAU);ctx.stroke();}if(e.bleedUntil>time){for(let i=0;i<(e.bleedStacks||1);i++)line([[e.x-5+i*4,e.y+1],[e.x-3+i*4,e.y+7]],'#df8293',1.5);}}

function drawPlaytestExtras(){for(let h of hearts)drawHeart(h);for(let e of enemies){drawEnemyHealth(e);drawStatus(e);}for(let t of scheduled)if(t.kind==='meteor'&&!t.done){let u=1-clamp(t.wait/t.fall,0,1),x=t.x+(1-u)*80,y=t.y-(1-u)*200;line([[x+23,y-55],[x,y]],'#efbeed88',9);line([[x+12,y-30],[x,y]],'#ffdfb9cc',4);starArt(x,y,13+u*4,time*4);}}
const PERKS={fire:{name:'Fire',color:'#f5a15a',text:'Hits burn enemies; fire damage grows with Power. Burning defeats spread fire to a nearby foe.'},ice:{name:'Ice',color:'#95dcf1',text:'Hits slow enemies by 30% for 1.2s. Refreshes rather than multiplying other slows.'},lightning:{name:'Lightning',color:'#e5d975',text:'Hits arc to a nearby foe: 8 base damage, growing with Power. At most once every 0.65s.'},vampiric:{name:'Vampiric',color:'#ba9ce5',text:'Steal 4% of actual hit damage as health, limited to 2 health/sec across all attacks and companions.'},wounding:{name:'Wounding',color:'#ee8c91',text:'Hits build up to three bleeds. Each stack starts at 3 damage/sec for 3s and grows with Power; stacks are rate-limited.'}};
let hearts=[],nextHeartAt=0,rewardRolls=[];

// The selected hero stays unique: Jodie covers the shop when Mimi is playable.
const SHOPKEEPER={x:719,y:379,reach:67,phase:0};
function shopkeeperKey(){return selected==='mimi'?'jodie':'mimi';}
function shopkeeperName(){return CHARACTERS[shopkeeperKey()].name;}
function shopkeeperGreeting(){return selected==='mimi'?'Heyy Mimiiii… How can I help you save us all?':'Okay human, you’re in my world now. Allow me to help you.';}
function shopkeeperNear(){return dist(p,SHOPKEEPER)<SHOPKEEPER.reach;}
function updateShopkeeper(dt){SHOPKEEPER.phase+=dt;}
function drawShopkeeper(){drawTownHero(shopkeeperKey(),SHOPKEEPER.x,SHOPKEEPER.y,SHOPKEEPER.phase*.4);townName(SHOPKEEPER.x,SHOPKEEPER.y,shopkeeperName().toUpperCase()+' · SHOP');if(shopkeeperNear()){ctx.fillStyle='#fff1ce';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText('TAP TO TALK',SHOPKEEPER.x,SHOPKEEPER.y+38);}}
function interactShopkeeper(direct=false){if(state!=='hub'||(!direct&&!shopkeeperNear()))return false;return openHubShop(direct);}

// world/burntwood-details.js — independent overworld dressing.
// Decorative scenery is intentionally deterministic and does not alter hitboxes.
const BURNTWOOD_BUILDINGS=[
 {x:68,y:265,w:72,h:65,type:0},{x:156,y:248,w:78,h:70,type:1},
 {x:252,y:300,w:70,h:58,type:2},{x:83,y:428,w:83,h:75,type:0},
 {x:194,y:455,w:65,h:62,type:1},{x:668,y:478,w:78,h:74,type:2},
 {x:762,y:521,w:70,h:63,type:0},{x:84,y:621,w:75,h:67,type:1},
 {x:211,y:604,w:72,h:61,type:2},{x:689,y:655,w:76,h:68,type:0},
 {x:760,y:729,w:73,h:66,type:1},{x:552,y:1112,w:82,h:69,type:2},
 {x:130,y:1157,w:74,h:65,type:0},{x:424,y:1146,w:75,h:66,type:1},
 {x:590,y:96,w:50,h:60,type:0},{x:656,y:100,w:49,h:59,type:1},
 {x:719,y:100,w:54,h:58,type:2}
];
function drawBurntwoodDetails(){
 // Distinct clusters of houses and shops around the hub paths.
 for(let i=0;i<BURNTWOOD_BUILDINGS.length;i++){let b=BURNTWOOD_BUILDINGS[i];drawBuilding(b,b.type);ctx.fillStyle=['#b35b4d','#638b6a','#d7b06a'][i%3];ctx.fillRect(b.x+5,b.y+b.h-18,b.w-10,6);}
 // Individual hedges, small flowering gardens and fences make the streets feel inhabited.
 for(let i=0;i<76;i++){let x=35+(i*163+Math.floor(i/9)*29)%825,y=50+(i*241+Math.floor(i/13)*47)%1180;
 if((x>565&&x<850&&y<355)||(x<330&&y>785&&y<1120)||(x>350&&x<540&&y>830&&y<1050))continue;
 ellipse(x,y,9+i%7,5+i%4,i%2?'#3f7447':'#527f50');
 if(i%3===0){ellipse(x-3,y-4,2,2,'#edb9b2');ellipse(x+4,y+1,2,2,'#e7d28b');}
 }
 // Benches, bins, lampposts and road signs, all decorative.
 for(let i=0;i<12;i++){let x=75+(i*199)%750,y=170+(i*283)%980;ctx.fillStyle='#69513d';ctx.fillRect(x,y,26,5);ctx.fillRect(x+3,y+5,3,11);ctx.fillRect(x+20,y+5,3,11);}
 for(let i=0;i<9;i++){let x=95+(i*173)%720,y=160+(i*257)%960;line([[x,y+18],[x,y-24]],'#343f3d',3);ellipse(x,y-25,7,7,'#f3e2ad');}
 // Wildlife and reeds by Chasewater.
 for(let i=0;i<21;i++){let x=20+(i*29)%250,y=835+(i*37)%290;line([[x,y+8],[x-3,y-8]],'#6b9969',2);}
 for(let i=0;i<7;i++){let x=36+i*29,y=925+(i%3)*35;ellipse(x,y,7,4,'#e9e6d7');ellipse(x+5,y-4,3,3,'#e9e6d7');}
 // Quarry warning signs and scattered rocks.
 for(let i=0;i<20;i++){let x=654+(i*41)%205,y=970+(i*59)%200;ellipse(x,y,4+i%6,3+i%3,'#9e8c73');}
 ctx.fillStyle='#f4d16e';ctx.fillRect(646,975,48,24);ctx.fillStyle='#4d4433';ctx.textAlign='center';ctx.font='bold 9px system-ui';ctx.fillText('QUARRY',670,990);
}

// world/hub.js — source of truth.
function finish(won,renderOnly=false){clearRewardNotice();if(state!=='playing')return;state=won?'won':'lost';if(won&&!renderOnly){awardBossEssence();run.visited=run.visited||[];if(!run.visited.includes(arenaKey))run.visited.push(arenaKey);}let more=won&&run.visited.length<JOURNEY_AREAS;$('panel').style.display='grid';$('upgradeChoices').style.display='none';$('back').style.display='block';$('panelButton').style.display='block';$('panelTitle').textContent=won?arena().short.toUpperCase()+' CLEARED':'GOOD RUN, '+stats().name.toUpperCase();$('panelName').textContent=won?arena().bossShort+' DEFEATED':'Have another go';$('panelText').textContent='Level '+run.level+' · '+run.history.length+' upgrades · '+kills+' enemies beaten'+(won?' · +2 ESSENCE · '+(run.lastEssenceSaved?'SAVED':'BACKUP NEEDED'):' · '+(run.essenceEarned||0)+' essence earned this run')+' · TOTAL '+progress.essence+' ESSENCE'+(saveNotice?' · '+saveNotice:'');$('continue').style.display=more?'block':'none';$('continue').textContent=run.perk?'RETURN TO BURNTWOOD':'CHOOSE PERK · RETURN TO BURNTWOOD';$('continue').onclick=()=>run.perk?continueRun():openBossReward();$('panelButton').textContent=won&&more?'END RUN · RETURN TO TOWN':'RETURN TO BURNTWOOD';$('panelButton').onclick=returnAfterRun;$('runSummary').style.display=more?'none':'block';if(!more)renderRunSummary(won);if(won&&run.charmPending)openCharmReward();}

function returnAfterRun(){if(!['won','lost'].includes(state))return false;hub.finished=true;p.hp=stats().hp;enterHub(false);return true;}

function continueRun(){if(state!=='won'||(run.visited||[]).length>=JOURNEY_AREAS)return;if(!run.perk){openBossReward();return;}recoverHealth(stats().hp*.2);enterHub(false);}

function startJourney(){reset();run.visited=[];hub.coins=0;applyStarter();enterHub(true);}

function enterHub(first=false){clearRewardNotice();state='hub';resetCharmArena();enemies=[];balls=[];enemyShots=[];pendingShots=[];gems=[];fx=[];warnings=[];hazards=[];scheduled=[];hearts=[];shrine=null;shrineBuff=null;boss=null;bossSpawned=false;p.action=null;p.swing=p.claws=null;p.frenzy=0;p.vx=p.vy=0;stick.x=stick.y=0;p.x=450;p.y=first?620:690;p.chargeCD=p.dodgeCD=0;resetCats();syncCats();resetDucks();resetMimi();resetJoseph();resetTom();resetHavannah();cam={x:p.x,y:p.y};hub.animals=Array.from({length:24},(_,i)=>({x:70+rand()*760,y:110+rand()*1080,a:rand()*TAU,t:rand()*3,kind:i%3}));$('inventoryButton').style.display='block';$('goldHud').style.display='block';$('newJourney').style.display=hub.finished?'block':'none';$('townDialogue').style.display=$('workshop').style.display='none';$('panel').style.display='none';$('bossHud').style.display='none';$('hubMap').style.display='block';$('hubMenu').style.display='block';$('shrineUse').style.display='none';$('hubShop').style.display='none';$('charge').firstChild.textContent='ENTER';$('dodge').firstChild.textContent='DODGE';updateHubHud();}

function hubPosition(x,y,r=14){x=clamp(x,35,865);y=clamp(y,65,1235);for(let b of hub.solids){let qx=clamp(x,b.x,b.x+b.w),qy=clamp(y,b.y,b.y+b.h),dx=x-qx,dy=y-qy,d=Math.hypot(dx,dy);if(d<r){if(d>.001){x=qx+dx/d*r;y=qy+dy/d*r;}else{let options=[{n:Math.abs(x-b.x),x:b.x-r,y},{n:Math.abs(x-b.x-b.w),x:b.x+b.w+r,y},{n:Math.abs(y-b.y),x,y:b.y-r},{n:Math.abs(y-b.y-b.h),x,y:b.y+b.h+r}].sort((a,b)=>a.n-b.n);x=options[0].x;y=options[0].y;}}}return{x,y};}

function stepHub(dt){hub.time+=dt;let dx=stick.x+(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),dy=stick.y+(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0),n=Math.hypot(dx,dy);if(n>1){dx/=n;dy/=n;}let sm=1-Math.exp(-dt*15);p.vx=lerp(p.vx,dx*stats().speed,sm);p.vy=lerp(p.vy,dy*stats().speed,sm);let q=hubPosition(p.x+p.vx*dt,p.y+p.vy*dt);p.x=q.x;p.y=q.y;p.walk+=Math.hypot(p.vx,p.vy)*dt*.065;if(n>.1)p.dir={x:dx/(n>1?1:n),y:dy/(n>1?1:n)};for(let c of cats){let a=c.slot*1.7,goal={x:p.x+Math.cos(a)*28,y:p.y+18+Math.sin(a)*12},d=dist(c,goal)||1,m=Math.min(d,175*dt);c.x+=(goal.x-c.x)/d*m;c.y+=(goal.y-c.y)/d*m;}for(let a of hub.animals){a.t-=dt;if(a.t<=0){a.a=rand()*TAU;a.t=1+rand()*4;}let q=hubPosition(a.x+Math.cos(a.a)*18*dt,a.y+Math.sin(a.a)*18*dt,5);a.x=q.x;a.y=q.y;}cam.x=lerp(cam.x,p.x,1-Math.exp(-dt*8));cam.y=lerp(cam.y,p.y,1-Math.exp(-dt*8));updateShopkeeper(dt);updateHubHud();}

function updateHubHud(){updateCharmHud();$('goldHud').textContent=hub.coins+' GOLD';hub.near=!hub.finished&&hub.portals.find(a=>dist(p,a)<75&&!run.visited?.includes(a.key))||null;hub.nearShop=shopkeeperNear();hub.nearWorkshop=workshopNear();hub.nearResident=townResidents().filter(n=>n.key!=='stef'&&dist(p,n)<55).sort((a,b)=>dist(p,a)-dist(p,b))[0]||null;$('arenaHud').textContent='BURNTWOOD · FIND A BOSS';$('timer').textContent=(run.visited?.length||0)+'/'+JOURNEY_AREAS+' CLEARED';$('hpText').textContent=Math.ceil(p.hp)+' / '+(Math.round(stats().hp*10)/10);$('hpFill').style.width=p.hp/stats().hp*100+'%';$('level').textContent='LV '+run.level;$('build').textContent=hub.nearWorkshop?'STEF’S SHED · '+progress.essence+' ESSENCE':hub.nearResident?'TALK TO '+CHARACTERS[hub.nearResident.key].name.toUpperCase():hub.near?'CHALLENGE '+ARENAS[hub.near.key].bossShort.toUpperCase():hub.nearShop?'TALK TO '+shopkeeperName().toUpperCase():hub.finished?'Start a new run when you’re ready':'Explore the real Burntwood landmarks';$('charge').firstChild.textContent=hub.nearShop||hub.nearResident?'TALK':hub.nearWorkshop?'UPGRADE':hub.finished?'NEW RUN':'CHALLENGE';actionButton('charge',!!(hub.near||hub.nearShop||hub.nearWorkshop||hub.nearResident||hub.finished),hub.nearShop||hub.nearResident?'TALK':hub.nearWorkshop?'ESSENCE':hub.near?'CHALLENGE':hub.finished?'START RUN':'FIND BOSS');actionButton('dodge',false,'SAFE HUB');$('perkHud').textContent='BUILD '+BUILD_ID+' · '+progress.essence+' ESSENCE';}

function enterNearby(){if(state==='hub'&&hub.nearWorkshop)return openWorkshop(false);if(state==='hub'&&hub.nearResident)return openConversation(hub.nearResident.key);if(state==='hub'&&hub.nearShop)return interactShopkeeper();if(state==='hub'&&hub.near)return enterArena(hub.near.key);if(state==='hub'&&hub.finished)startJourney();}

function enterArena(key){if(state!=='hub'||hub.finished||!ARENAS[key]||run.visited?.includes(key))return false;if(!run.started){let old=stats().hp;run.permanent={...progress.heroes[selected]};p.hp+=stats().hp-old;run.started=true;}arenaKey=key;run.stage=run.visited?.length||0;run.stagePicks=0;run.earned=0;resetCharmArena();resetPark();goldDrops=[];run.offers=[];time=0;enemies=[];balls=[];enemyShots=[];pendingShots=[];gems=[];fx=[];warnings=[];hazards=[];scheduled=[];decoy=null;hearts=[];nextHeartAt=0;boss=null;bossSpawned=false;nextSpawn=.8;p.x=450;p.y=780;p.vx=p.vy=0;p.extX=p.extY=0;p.action=null;p.swing=p.claws=null;p.frenzy=0;p.catTarget=null;p.hitIds.clear();p.inv=1.5;p.attack=.4;p.chargeCD=p.dodgeCD=0;resetCats();syncCats();resetDucks();resetMimi();resetJoseph();resetTom();resetHavannah();cam={x:p.x,y:p.y};state='playing';$('newJourney').style.display='none';$('hubMap').style.display='none';$('hubMenu').style.display='block';$('charge').firstChild.textContent=isHavannah()?'TANTRUM':isTom()?'QUAKE':isJoseph()?'OVERHYPE!':isMimi()?'NINE LIVES':isEvie()?'ASSEMBLE':isJodie()?'KITTENS':isStef()?'BY ORDER!':isAva()?'GLITTER':'CHARGE';$('dodge').firstChild.textContent=isStef()?'PUSH':'DODGE';$('arenaHud').textContent=arena().name.toUpperCase();$('bossHud').style.display='none';$('panel').style.display='none';shrineBuff=null;shrine=rewardRandom()<.2?{x:arenaKey==='chasewater'?380:180,y:600,used:false}:null;updateHud();return true;}

function drawBuilding(b,i){ctx.fillStyle='#233e3444';ctx.fillRect(b.x+8,b.y+10,b.w,b.h);ctx.fillStyle=['#ad9a7a','#a88c76','#9c9c85'][i%3];ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#66574f';ctx.beginPath();ctx.moveTo(b.x-6,b.y+12);ctx.lineTo(b.x+b.w/2,b.y-24);ctx.lineTo(b.x+b.w+6,b.y+12);ctx.closePath();ctx.fill();for(let x=b.x+18;x<b.x+b.w-15;x+=32){ctx.fillStyle='#b8d7cc';ctx.fillRect(x,b.y+32,16,18);line([[x+8,b.y+32],[x+8,b.y+50]],'#6f7466',1);}ctx.fillStyle='#504a40';ctx.fillRect(b.x+b.w/2-10,b.y+b.h-27,20,27);}


function mapTree(x,y,r){ellipse(x+3,y+6,r,r*.6,'#294c34');ellipse(x-4,y-5,r*.82,r*.75,'#48754a');ellipse(x+4,y-9,r*.5,r*.5,'#6c9759');}
function mapLabel(x,y,name){ctx.fillStyle='#493c2c';ctx.fillRect(x-59,y-29,118,27);ctx.strokeStyle='#d4b475';ctx.lineWidth=2;ctx.strokeRect(x-59,y-29,118,27);ctx.textAlign='center';ctx.fillStyle='#ffebbb';ctx.font='bold 12px Georgia';ctx.fillText(name,x,y-11);}
