function drawTom(){ctx.save();for(let w of tom.waves)if(w.wait<=0){let u=Math.min(1,w.age/w.duration),r=w.r*u;ctx.save();ctx.globalAlpha=Math.max(0,1-w.age/(w.duration+.12));ctx.strokeStyle=w.launch?'#ffdb8e':'#d4b878';ctx.lineWidth=w.launch?5:3;ctx.beginPath();ctx.arc(w.x,w.y,r,0,TAU);ctx.stroke();for(let n=0;n<8;n++){let a=n*TAU/8;line([[w.x+Math.cos(a)*r*.55,w.y+Math.sin(a)*r*.55],[w.x+Math.cos(a+.08)*r*.8,w.y+Math.sin(a+.08)*r*.8],[w.x+Math.cos(a)*r,w.y+Math.sin(a)*r]],'#a08b62',1.5);}ctx.restore();}if(p.inv>0&&Math.floor(p.inv*20)%2===0)ctx.globalAlpha=.65;drawTomBody(p.x,p.y,time*1.2+Math.sin(p.walk||0)*.15,{dir:p.dir,punch:tom.punch,paw:tom.paw,aim:tom.aim,double:tom.double,upper:tom.upper,slam:tom.slam,barge:!!tom.barge,dead:state==='lost'});if(tom.rebound)starArt(p.x+25,p.y-16,3,time*3);ctx.restore();}
