// Havannah — Tiny Rebel identity; build/tuning delegated by the user for playtest.
const isHavannah=()=>selected==='havannah';
let havannah;
function resetHavannah(){havannah={attacks:0,hits:0,shots:[],queue:[],rings:[],tantrum:null,skip:null,decoy:null,cast:0,aim:0,paw:0};}
resetHavannah();
const havAnchored=e=>e.kind==='boss'||e.heroic;
const havSmall=e=>!havAnchored(e)&&!['heavy','bruiser','badger'].includes(e.kind);
function havSound(){if(typeof window==='undefined')return;try{let a=havSound.audio;if(!a||a.state!=='running')return;let o=a.createOscillator(),g=a.createGain(),at=a.currentTime;o.type='sine';o.frequency.setValueAtTime(540,at);o.frequency.exponentialRampToValueAtTime(220,at+.07);g.gain.setValueAtTime(.025,at);g.gain.exponentialRampToValueAtTime(.001,at+.1);o.connect(g);g.connect(a.destination);o.start();o.stop(at+.11);}catch{}}
function havWakeSound(){if(!isHavannah())return;try{let Audio=window.AudioContext||window.webkitAudioContext;if(Audio){havSound.audio??=new Audio();havSound.audio.resume();}}catch{}}
function havShot(x,y,angle,damage,mini=false,source='weapon'){if(havannah.shots.length>=72)return;havannah.shots.push({x,y,px:x,py:y,vx:Math.cos(angle)*(mini?280:390),vy:Math.sin(angle)*(mini?280:390),damage,mini,source,r:mini?3.5:5.5,life:mini?.65:1.8,hit:new Set(),remaining:!mini&&tier>=5?3:1,spin:0});}
function havAttack(){if(!isHavannah()||havannah.skip||p.action)return false;let e=nearest(p,new Set(),400);if(!e)return false;let a=Math.atan2(e.y-p.y,e.x-p.x),damage=CHARACTERS.havannah.damage*(tier>=1?1.15:1);havannah.attacks++;havannah.aim=a;havannah.paw=1-havannah.paw;havannah.cast=.16;havShot(p.x,p.y-3,a,damage);if(tier>=4&&havannah.attacks%3===0)havannah.queue.push({wait:.1,angle:a,damage});havannah.queue=havannah.queue.slice(-8);havSound();return true;}
function havSparkBurst(e){let count=tier>=3?5:3,damage=(tier>=3?4.5:3)*(tier>=1?1.15:1);for(let n=0;n<count;n++)havShot(e.x,e.y,n*TAU/count,damage,true);pop(e.x,e.y,'#77ece6',9);}
function havRing(x,y,r){havannah.rings.push({x,y,r,life:.35});havannah.rings=havannah.rings.slice(-12);}
