// Run-only charms. All proc damage is source='charm' and cannot trigger other procs.
function charmRank(key){let c=run.charms?.find(c=>c.key===key);return c?.rank||0;}
function charmPower(key){let rank=charmRank(key);return rank?1+(rank-1)*.5:0;}
function resetCharms(){run.charms=[];run.charmBag=[];run.charmOffers=[];run.charmPending=false;resetCharmArena();}
function resetCharmArena(){resetHeroicEncounter();run.charmPending=false;run.charmOffers=[];run.charmFX={stormAt:0,bell:0,bellAt:0,attacks:0,echo:false,queue:[],patches:[],patchTick:0,thornAt:0,defeats:0,safe:0,shield:false,guardRank:charmRank('guardian'),lastDodge:false,dryHits:0,critAt:0,still:0,bloodBudget:2,lanternUsed:false,phantom:null};}
function gainCharm(key){let old=p?stats().hp:0;if(!CHARMS[key])return false;let c={key,rank:1};if(run.charms.length<3&&!charmRank(key))run.charms.push(c);else run.charmBag.push(c);if(p)p.hp=Math.min(stats().hp,p.hp+(run.charmFX?.lanternUsed?0:Math.max(0,stats().hp-old)));return true;}
function fusionPair(){let all=[...run.charms,...run.charmBag];for(let a of all)if(a.rank<3){let b=all.find(c=>c!==a&&c.key===a.key&&c.rank===a.rank);if(b)return[a,b];}return null;}
function fuseCharm(){if(state!=='shop'||hub.finished)return false;let pair=fusionPair();if(!pair)return false;let[a,b]=pair,rank=a.rank+1,key=a.key,equipped=run.charms.includes(a)||run.charms.includes(b);run.charms=run.charms.filter(c=>c!==a&&c!==b);run.charmBag=run.charmBag.filter(c=>c!==a&&c!==b);let c={key,rank};if(equipped)run.charms.push(c);else{let slot=run.charms.findIndex(old=>old.key===key&&old.rank<rank);if(slot>=0){run.charmBag.push(run.charms[slot]);run.charms[slot]=c;}else run.charmBag.push(c);}p.hp=Math.min(p.hp,stats().hp);renderCharmWorkshop();updateCharmHud();return true;}
function equipCharm(index,slot){if(state!=='shop'||hub.finished||!run.charmBag[index])return false;let c=run.charmBag[index];if(charmRank(c.key))return false;if(run.charms.length>=3&&!(slot>=0&&slot<3))return false;run.charmBag.splice(index,1);if(run.charms.length<3)run.charms.push(c);else{let old=run.charms[slot];run.charms[slot]=c;run.charmBag.push(old);}p.hp=Math.min(p.hp,stats().hp);renderCharmWorkshop();updateCharmHud();return true;}
function charmCaption(c){return CHARMS[c.key].icon+' '+CHARMS[c.key].name+' · '+RARITIES[CHARMS[c.key].rarity].name+' · '+['','I','II','III'][c.rank];}
function charmDetail(c){let r=c.rank,p=1+(r-1)*.5,key=c.key;let details={sturdy:'+'+(10*p)+' health.',iron:'+'+(3*p)+' armour.',running:'+'+(6*p)+'% movement.',quick:'+'+(8*p)+'% attack speed.',keen:'+'+(8*p)+' points critical chance.',heavy:'+'+(25*p)+' points critical damage.',scavenger:'+'+(25*p)+'% pickup range.',mender:'+'+(20*p)+'% healing received.',patient:(6-r)+' eligible non-critical hits: next guaranteed crit. Any crit resets.',watch:'Special cooldown −'+(15*p)+'%.',hunter:'+'+(20*p)+'% damage to heroic/final bosses.',frost:'Slow '+Math.min(40,20*p)+'% for 1.5s; bosses resist.',opportunist:'+'+(20*p)+'% normal damage to controlled foes.',glass:'+'+(30*p)+'% normal damage; −20% max health.',still:'Stand still 1s: +'+(25*p)+'% normal damage.',blunt:'+'+(25*p)+'% normal damage; criticals DISABLED.',clockwork:'Special cooldown −'+(30*p)+'%; attack speed −'+(15*p)+'%.',blood:'Normal hits heal '+(2*p)+'% damage, max 2 HP/s. Other healing −30%.',phantom:'Special: 4s shadow mirrors normal hits at '+(30+10*r)+'% power. Special cooldown +20%.',lantern:'Once/arena: survive at 1 HP, 2s invulnerable; no healing after rescue, +25% normal damage.',storm:'Chains to 2 foes for '+Math.round(8*p)+' damage; 1.5s cooldown.',bell:'8 qualifying hits: '+Math.round(12*p)+' damage shockwave.',locket:'Every 12 defeats: '+Math.round(10*p)+' healing pickup.',echo:'Every fifth normal attack primes one '+Math.round(.4*p*100)+'% echo.',thorn:'Taking damage: '+Math.round(18*p)+' damage burst; 3s cooldown.',ember:'2s patch: '+Math.round(4*p)+' damage/0.5s, maximum 8.',moon:'Dodge through: next normal hit +'+Math.round(.5*p*100)+'%; 4s mark.',guardian:'Shield after '+(r===1?20:r===2?16:12)+'s without damage.',bramble:'Knockback: +'+Math.round(.15*p*100)+'% damage for 2s.',purse:'Starting charm only: 100 gold once. No gold from re-equipping.'};return details[key]||CHARMS[key].text;}
function rollCharmKey(min=0){let rarity=rollRarity(min),pool=Object.keys(CHARMS).filter(k=>k!=='purse'&&CHARMS[k].rarity===rarity);return pool[Math.min(pool.length-1,Math.floor(rewardRandom()*pool.length))];}
function rollCharmOffers(){let chosen=[];chosen.push(rollCharmKey(run.stage>=3?3:2));if(run.stage<3&&run.charms.length&&rewardRandom()<.5){let copy=run.charms.filter(c=>c.key!=='purse'&&c.rank<3);if(copy.length)chosen.push(copy[Math.floor(rewardRandom()*copy.length)].key);}for(let n=0;chosen.length<3&&n<100;n++){let key=rollCharmKey();if(!chosen.includes(key))chosen.push(key);}if(chosen.length<3)for(let key of Object.keys(CHARMS))if(key!=='purse'&&!chosen.includes(key)&&chosen.length<3)chosen.push(key);return chosen;}
function openCharmReward(){if(!['playing','won'].includes(state)||!run.charmPending)return false;run.charmPending=false;run.charmResume=state;run.charmOffers=rollCharmOffers();clearRewardNotice();state='charm';$('panel').style.display='grid';$('panelTitle').textContent='HEROIC SPOILS · CHOOSE ONE';$('panelName').textContent='A new twist for this run';$('panelText').textContent='One guaranteed Rare+ charm; Epic+ in areas 4–5. Three slots. Bag copies can be fused in town.';for(let id of ['continue','panelButton','back'])$(id).style.display='none';$('upgradeChoices').style.display='grid';$('upgradeChoices').innerHTML=run.charmOffers.map((key,i)=>'<button class="upgradeCard charmCard" style="--rarity:'+CHARMS[key].color+'" data-choice="'+i+'"><span>'+RARITIES[CHARMS[key].rarity].symbol+' '+RARITIES[CHARMS[key].rarity].name.toUpperCase()+' · RUN CHARM'+(charmRank(key)?' · FUSION COPY':'')+'</span><b>'+CHARMS[key].name+'</b><small>'+charmDetail({key,rank:1})+'</small><em class="rewardHint">'+charmRewardHint(key)+'</em></button>').join('');for(let i=0;i<3;i++)$('upgradeChoices').children[i].onclick=()=>chooseCharm(i);return true;}
function chooseCharm(index){if(state!=='charm'||!run.charmOffers[index])return false;let key=run.charmOffers[index],hint=charmRewardHint(key);gainCharm(key);run.charmOffers=[];state='playing';$('panel').style.display='none';$('upgradeChoices').style.display='none';if(run.charmResume==='won')finish(true,true);else rewardNotice(RARITIES[CHARMS[key].rarity].name.toUpperCase()+' CHARM',CHARMS[key].name+' · '+hint,CHARMS[key].color);updateCharmHud();return true;}
function updateCharmHud(){let el=$('charmHud'),visible=['playing','hub','shop','charm','upgrade'].includes(state);el.style.display=visible?'flex':'none';$('charmBagCount').style.display=visible?'block':'none';let signature=JSON.stringify(run.charms||[])+':'+(run.charmBag?.length||0);if(el.dataset.signature===signature)return;el.dataset.signature=signature;el.innerHTML=[0,1,2].map(i=>{let c=run.charms?.[i];return '<span title="'+(c?CHARMS[c.key].name:'Empty charm slot')+'">'+(c?CHARMS[c.key].icon+(c.rank>1?' '+c.rank:''):'◇')+'</span>';}).join('');$('charmBagCount').textContent=run.charmBag?.length?'BAG '+run.charmBag.length:'';}
function renderCharmWorkshop(){let el=$('charmWorkshop'),pair=hub.finished?null:fusionPair();el.innerHTML='<h3>CHARMS · THIS RUN ONLY</h3><p>Equip 3 different charms. Merge 2 matching copies of the same rank. Maximum rank III.</p>'+run.charms.map((c,i)=>'<div class="charmOwned"><b>'+charmCaption(c)+'</b><small>'+charmDetail(c)+'</small></div>').join('')+(run.charms.length?'':'<p>Defeat a heroic enemy after 0:45 to find your first charm.</p>')+run.charmBag.map((c,i)=>'<div class="charmOwned"><b>BAG · '+charmCaption(c)+'</b><small>'+charmDetail(c)+'</small>'+(!charmRank(c.key)?run.charms.length<3?'<button data-equip="'+i+'" data-slot="-1">EQUIP</button>':run.charms.map((old,slot)=>'<button data-equip="'+i+'" data-slot="'+slot+'">REPLACE '+CHARMS[old.key].name+'</button>').join(''):'<small>Matching copies can be fused below.</small>')+'</div>').join('')+'<button id="fuseCharm" '+(!pair?'disabled':'')+'>'+(pair?'MERGE 2 × '+CHARMS[pair[0].key].name+' → RANK '+(pair[0].rank+1):'NEED 2 MATCHING COPIES TO MERGE')+'</button>';
if(hub.finished)for(let b of el.querySelectorAll?.('button')||[])b.disabled=true;$('fuseCharm').onclick=fuseCharm;for(let b of el.querySelectorAll?.('[data-equip]')||[])b.onclick=()=>equipCharm(+b.dataset.equip,+b.dataset.slot);}
function charmAttackStarted(){let f=run.charmFX;if(!f)return;f.attacks++;if(charmRank('echo')&&f.attacks%5===0)f.echo=true;}
function charmMultiplier(e,source,dx,dy){if(source==='charm'||source==='clone')return 1;let mult=1;if(charmRank('hunter')&&(e.heroic||e.kind==='boss'))mult+=.20*charmPower('hunter');if(charmRank('bramble')&&(dx||dy)&&e.kind!=='boss'&&source!=='status'&&source!=='perk')e.charmExposeUntil=time+2;if(e.charmExposeUntil>time&&charmRank('bramble'))mult+=.15*charmPower('bramble');if(['weapon','cat'].includes(source)&&charmRank('opportunist')&&(e.slowUntil>time||e.charmFrostUntil>time||e.stunUntil>time))mult+=.2*charmPower('opportunist');if(['weapon','cat'].includes(source)&&e.charmMoonUntil>time){mult+=.5*charmPower('moon');e.charmMoonUntil=0;}return mult;}
function charmOnHit(e,actual,source){if(!['weapon','cat','special'].includes(source)||actual<=0||!run.charmFX)return;let f=run.charmFX;
if(charmRank('storm')&&time>=f.stormAt){f.stormAt=time+1.5;let seen=new Set([e.id]),from=e;for(let i=0;i<2;i++){let other=nearest(from,seen,140);if(!other)break;seen.add(other.id);f.queue.push({kind:'damage',target:other,amount:8*charmPower('storm'),wait:.04});fx.push({x:from.x,y:from.y,vx:0,vy:0,life:.2,max:.2,arcX:other.x,arcY:other.y,color:'#f3e49b',r:0});from=other;}}
if(charmRank('frost')&&e.hp>0)e.charmFrostUntil=time+1.5;
if(charmRank('bell')&&time>=(e.charmBellAt||0)){e.charmBellAt=time+.15;f.bell++;if(f.bell>=8&&time>=f.bellAt){f.bell=0;f.bellAt=time+.5;f.queue.push({kind:'burst',x:p.x,y:p.y,r:95,amount:12*charmPower('bell'),wait:.04});}}
if(['weapon','cat'].includes(source)&&charmRank('blood')&&f.bloodBudget>0){let heal=recoverHealth(Math.min(actual*.02*charmPower('blood'),f.bloodBudget/Math.max(.01,healingFactor(true))),'blood');f.bloodBudget=Math.max(0,f.bloodBudget-heal);}if(['weapon','cat'].includes(source)&&f.phantom&&time>=f.phantom.at){f.phantom.at=time+.2;let target=nearest(f.phantom,new Set(),350);if(target){f.queue.push({kind:'clone',target,amount:actual*(.3+.1*charmRank('phantom')),wait:.18});fx.push({x:f.phantom.x,y:f.phantom.y,vx:0,vy:0,life:.2,max:.2,arcX:target.x,arcY:target.y,color:'#bba5dd',r:0});}}if(charmRank('echo')&&source==='weapon'&&f.echo){f.echo=false;f.queue.push({kind:'damage',target:e,amount:actual*.4*charmPower('echo'),wait:.16});radialEffect(e.x,e.y,22,'#e6d596');}}
function charmOnKill(e){let f=run.charmFX;if(!f)return;f.defeats++;if(charmRank('locket')&&f.defeats%12===0&&hearts.length<10)hearts.push({x:e.x,y:e.y,life:30,heal:10*charmPower('locket')});if(charmRank('ember')){f.patches.push({x:e.x,y:e.y,r:30,life:2});if(f.patches.length>8)f.patches.shift();}}
function charmBlock(){let f=run.charmFX;if(charmRank('guardian')&&f?.shield){f.shield=false;f.safe=0;p.inv=.3;radialEffect(p.x,p.y,32,'#afdbc8');float(p.x,p.y-30,'BLOCK','#afdbc8');return true;}return false;}
function charmHurt(){let f=run.charmFX;if(!f)return;f.safe=0;if(charmRank('thorn')&&time>=f.thornAt){f.thornAt=time+3;f.queue.push({kind:'burst',x:p.x,y:p.y,r:100,amount:18*charmPower('thorn'),wait:.04});}}
function charmDodgeMarks(){if(!charmRank('moon'))return;for(let e of enemies)if(e.hp>0&&dist(p,e)<p.r+e.r+10)e.charmMoonUntil=time+4;}
function stepCharms(dt){let f=run.charmFX;if(!f)return;for(let task of f.queue){task.wait-=dt;if(task.wait>0)continue;task.done=true;if(task.kind==='damage'||task.kind==='clone'){if(task.target.hp>0)damageEnemy(task.target,task.amount,0,0,false,task.kind==='clone'?'clone':'charm');}else{radialEffect(task.x,task.y,task.r,'#dfc18a');for(let e of enemies)if(e.hp>0&&dist(task,e)<task.r+e.r){let n=dist(task,e)||1;damageEnemy(e,task.amount,(e.x-task.x)/n,(e.y-task.y)/n,true,'charm');}}}f.queue=f.queue.filter(t=>!t.done).slice(-48);
f.bloodBudget=Math.min(2,(f.bloodBudget||0)+2*dt);f.still=Math.hypot(p.vx,p.vy)<8?f.still+dt:0;if(f.phantom){f.phantom.left-=dt;f.phantom.x=lerp(f.phantom.x,p.x+40,dt*4);f.phantom.y=lerp(f.phantom.y,p.y+15,dt*4);if(f.phantom.left<=0)f.phantom=null;}f.safe+=dt;let guard=charmRank('guardian');if(guard!==f.guardRank){f.safe=0;f.shield=false;f.guardRank=guard;}if(guard&&f.safe>=(guard===1?20:guard===2?16:12))f.shield=true;
for(let patch of f.patches)patch.life-=dt;f.patches=f.patches.filter(x=>x.life>0);f.patchTick-=dt;if(f.patchTick<=0){f.patchTick=.5;for(let e of enemies)if(e.hp>0&&f.patches.some(a=>dist(a,e)<a.r+e.r))damageEnemy(e,4*charmPower('ember'),0,0,false,'charm');}
if(p.action==='dodge'||p.action==='push')charmDodgeMarks();
if(charmRank('bramble'))for(let e of enemies)if(e.hp>0&&Math.hypot(e.kx,e.ky)>45)e.charmExposeUntil=time+2;
updateCharmHud();}
function drawCharmEffects(){let f=run.charmFX;if(!f)return;for(let a of f.patches){ctx.save();ctx.globalAlpha=Math.min(.32,a.life*.3);ellipse(a.x,a.y,30,21,'#ed9b5c');ctx.restore();}if(f.phantom){ctx.save();if(selected==='mimi')drawMimiBody(f.phantom.x,f.phantom.y,.35);else{ctx.globalAlpha=.35;drawTownHero(selected,f.phantom.x,f.phantom.y);}ctx.restore();radialDraw(f.phantom.x,f.phantom.y,25,'#bba6df');}if(f.shield)radialDraw(p.x,p.y,29,'#afdbc8');for(let e of enemies)if(e.hp>0){if(e.heroic){radialDraw(e.x,e.y,e.r+8,'#f2ce77');ctx.fillStyle='#f6df9f';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText('★ HEROIC',e.x,e.y-e.r-26);}if(e.charmMoonUntil>time)starArt(e.x,e.y-e.r-8,4,time);}}
function charmSpecialFactor(){return charmRank('phantom')?1.2:1;}
function charmSlowFactor(e){let slow=Math.min(.4,.20*charmPower('frost'))*(e.kind==='boss'?.4:e.heroic?.6:1);return e.slowUntil>time?(1-Math.max(.3,slow))/.7:1-slow;}

function charmSpecialUsed(){let f=run.charmFX;if(charmRank('phantom')&&f)f.phantom={x:p.x+40,y:p.y,left:4,at:0};}
function charmRescue(){let f=run.charmFX;if(!charmRank('lantern')||!f||f.lanternUsed)return false;f.lanternUsed=true;p.hp=1;p.inv=2;radialEffect(p.x,p.y,125,'#f4ce70');float(p.x,p.y-45,'LAST LIGHT!','#f4ce70');for(let e of enemies)if(e.hp>0&&dist(p,e)<125+e.r){let n=dist(p,e)||1,m=e.kind==='boss'?.1:1;e.kx+=(e.x-p.x)/n*250*m;e.ky+=(e.y-p.y)/n*250*m;}return true;}

// Chase Terrace Park: rival cats and the fictional Umbrella Man. No existing arena AI is changed.
ARENAS.park={name:'Chase Terrace Park',short:'Chase Terrace Park',boss:'Umbrella Man',bossShort:'UMBRELLA MAN'};
const PARK_PILES=[{x:165,y:280},{x:730,y:480},{x:270,y:1060}];
let parkPiles=[],parkSlips=[];
function resetPark(){parkPiles=PARK_PILES.map(p=>({...p,charge:1}));parkSlips=[];}
function parkWave(){let pool=['scrapper','pouncer','bandit','bruiser','spitter'],n=Math.min(4,Math.floor(time/16)+(run.stage>1?1:0));spawnPark(pool[Math.floor(rand()*(n+1))]);if(time>30&&rand()<.3)spawnPark('scrapper');nextSpawn=stageSpawnDelay(Math.max(.65,1.05-time*.002));}
function spawnPark(kind,at){kind=({swarm:'scrapper',charger:'pouncer',heavy:'bruiser'}[kind]||kind);let spec={scrapper:[30,14,62],pouncer:[42,15,55],bandit:[32,13,65],bruiser:[110,24,32],spitter:[44,15,38],patch:[300,27,65],boss:[1150,25,48]}[kind]||[30,14,62],a=rand()*TAU,q=walkable(at?.x??p.x+Math.cos(a)*310,at?.y??p.y+Math.sin(a)*310,spec[1]);let e={id:++id,kind,park:true,x:q.x,y:q.y,hp:spec[0],maxHp:spec[0],r:spec[1],speed:spec[2],kx:0,ky:0,flash:0,stagger:0,age:0,attackCD:0,mode:'walk',timer:1.5,sequence:0,dx:0,dy:1,healUsed:0};applyEnemyScale(e);enemies.push(e);if(kind==='boss'){boss=e;bossSpawned=true;float(p.x,p.y-65,'UMBRELLA MAN ARRIVES','#f3ce85');}return e;}
function parkHit(e,actual,source){if(!e.park||e.kind!=='boss'||e.mode!=='collect'||actual<=0)return;e.interrupt=(e.interrupt||0)+actual;if(e.interrupt>=e.maxHp*.015){e.mode='recover';e.timer=1.4;e.interrupt=0;float(e.x,e.y-60,'INTERRUPTED!','#f2d384');}}
function parkDamageFactor(e){if(!e.park||e.kind!=='boss'||e.mode!=='shield')return 1;let a=Math.atan2(p.y-e.y,p.x-e.x),d=Math.atan2(Math.sin(a-e.aim),Math.cos(a-e.aim));return Math.abs(d)<1.25?.25:1;}
function parkStrike(e,range,wide,damage){let a=Math.atan2(p.y-e.y,p.x-e.x),delta=Math.atan2(Math.sin(a-e.aim),Math.cos(a-e.aim));if(dist(p,e)<range+p.r&&Math.abs(delta)<wide)hurt(damage,e);radialEffect(e.x,e.y,range,'#d6be92');}
function stepParkEnemy(e,dt){let goal=enemyGoal(e),dx=goal.x-e.x,dy=goal.y-e.y,n=Math.hypot(dx,dy)||1,mx=dx/n,my=dy/n,speed=e.speed,isBoss=e.kind==='boss';
 if(e.stunUntil>time){speed=0;e.timer+=dt;}
 else if(e.mode==='collect'){speed=0;if(e.timer<=0){let pile=parkPiles[e.pile];if(pile?.charge&&e.healUsed<.15*e.maxHp){let heal=Math.min(e.maxHp*.05,.15*e.maxHp-e.healUsed,e.maxHp-e.hp);e.hp+=heal;e.healUsed+=heal;pile.charge=0;float(e.x,e.y-60,'+'+Math.round(heal)+' HEAL','#a9e4ac');radialEffect(e.x,e.y,45,'#8fcf96');}e.mode='recover';e.timer=1.2;}}
 else if(e.mode==='seekRubbish'){let pile=parkPiles[e.pile],d=dist(e,pile)||1;mx=(pile.x-e.x)/d;my=(pile.y-e.y)/d;if(d<20){e.mode='collect';e.timer=1.6;e.interrupt=0;}}
 else if(e.mode==='shield'){speed=0;if(e.timer<=0){e.mode='recover';e.timer=.7;}}
 else if(e.mode==='wind'){speed=0;if(e.timer<=0){if(e.move==='pounce'){e.mode='pounce';e.timer=.4;}else if(e.move==='rush'){e.mode='rush';e.timer=.65;}else{parkStrike(e,isBoss?100:e.kind==='bruiser'?70:55,1.25,isBoss?16:7);e.swipes=(e.swipes||0)-1;if(e.swipes>0){e.timer=.3;e.aim=Math.atan2(p.y-e.y,p.x-e.x);}else{e.mode='recover';e.timer=isBoss?.9:1.1;}}}}
 else if(e.mode==='rush'){mx=e.dx;my=e.dy;speed=340;if(e.timer<=0){e.mode='recover';e.timer=1.5;float(e.x,e.y-45,'STUCK!','#efdfa6');}}
 else if(e.mode==='pounce'){let d=Math.hypot(e.tx-e.x,e.ty-e.y)||1;mx=(e.tx-e.x)/d;my=(e.ty-e.y)/d;speed=Math.min(420,d/Math.max(dt,.001));if(e.timer<=0||d<8){if(dist(p,e)<e.r+p.r+18)hurt(e.kind==='patch'?11:8,e);if(e.kind==='patch'){e.move='swipe';e.mode='wind';e.swipes=3;e.timer=.5;e.aim=Math.atan2(dy,dx);}else{e.mode='recover';e.timer=1.1;}}}
 else if(e.mode==='recover'){speed=0;if(e.timer<=0){e.mode='walk';e.timer=isBoss&&e.hp<e.maxHp*.5?.65:1.3;}}
 else if(e.kind==='bandit'){let index=e.carry?e.delivery:e.pick;if(index===undefined){index=Math.floor(rand()*parkPiles.length);e.pick=index;}let pile=parkPiles[index],d=dist(e,pile)||1;mx=(pile.x-e.x)/d;my=(pile.y-e.y)/d;if(d<20){if(!e.carry){e.carry=true;e.delivery=(index+1)%parkPiles.length;}else{if(parkPiles[e.delivery].charge===0)parkPiles[e.delivery].charge=1;e.carry=false;e.pick=(index+1)%parkPiles.length;}}}
 else if(e.kind==='spitter'){if(n<160){mx=-mx;my=-my;}else if(n<245)speed=0;if(e.timer<=0){let a=Math.atan2(dy,dx);enemyShots.push({x:e.x,y:e.y,px:e.x,py:e.y,vx:Math.cos(a)*160,vy:Math.sin(a)*160,r:7,life:2.4,damage:5,damageScale:e.damageScale,parkHair:true});e.timer=2.6;parkSlips.push({x:p.x,y:p.y,wait:.8,life:2.8,r:28});}}
 else if(e.timer<=0&&n<370){if(isBoss&&e.hp<e.maxHp*.75&&e.healUsed<e.maxHp*.15&&e.sequence%3===1){let ix=parkPiles.findIndex(a=>a.charge);if(ix>=0){e.pile=ix;e.mode='seekRubbish';e.timer=0;e.sequence++;}}
 if(e.mode==='walk'){e.aim=Math.atan2(dy,dx);e.dx=mx;e.dy=my;if(isBoss&&e.sequence%4===2){e.mode='shield';e.timer=1.8;}else{e.move=e.kind==='patch'||e.kind==='pouncer'?'pounce':isBoss&&e.sequence%2?'rush':'swipe';e.mode='wind';e.timer=e.move==='pounce'?.8:.75;e.tx=p.x;e.ty=p.y;e.swipes=e.kind==='patch'?3:e.kind==='scrapper'?2:1;}e.sequence++;}}
 if(e.slowUntil>time)speed*=.7;if(e.charmFrostUntil>time)speed*=charmSlowFactor(e);if(e.stagger>0)speed*=.2;let q=walkable(e.x+mx*speed*dt+e.kx*dt,e.y+my*speed*dt+e.ky*dt,e.r);e.x=q.x;e.y=q.y;e.kx*=Math.exp(-dt*8);e.ky*=Math.exp(-dt*8);applyChaseContact(e);
}
function stepPark(dt){for(let h of parkSlips){h.wait-=dt;h.life-=dt;}parkSlips=parkSlips.filter(h=>h.life>0).slice(-12);}
function parkMovementFactor(){return arenaKey==='park'&&parkSlips.some(h=>h.wait<=0&&dist(p,h)<h.r)? .65:1;}
function drawParkGround(){ctx.fillStyle='#618255';ctx.fillRect(0,0,900,1300);for(let y=80;y<1300;y+=105)line([[40,y],[860,y-20]],'#719160',25);line([[130,100],[455,640],[800,1190]],'#c0ad85',85);line([[80,970],[750,280]],'#c0ad85',60);for(let [x,y] of [[125,500],[690,820],[540,190],[380,1140]]){ctx.fillStyle='#6d513c';ctx.fillRect(x,y,85,10);ctx.fillRect(x+8,y+10,6,12);ctx.fillRect(x+70,y+10,6,12);}for(let [x,y] of [[140,180],[720,1110],[60,730],[815,530]]){ellipse(x,y,28,24,'#365f40');ellipse(x-8,y-8,22,19,'#4b784d');}line([[580,1000],[580,910],[700,910],[700,1000]],'#9b7562',9);line([[600,930],[600,990]],'#c9c5a1',3);line([[680,930],[680,990]],'#c9c5a1',3);line([[600,990],[680,990]],'#a7b1ac',4);for(let pile of parkPiles){ctx.fillStyle='#3c5345';ctx.fillRect(pile.x-12,pile.y-18,24,32);ellipse(pile.x,pile.y-18,14,5,'#52675a');if(pile.charge){ellipse(pile.x+19,pile.y+12,9,6,'#a6a18a');line([[pile.x+15,pile.y+8],[pile.x+24,pile.y+13]],'#e8d8ad',3);}}ctx.fillStyle='#f1dfac';ctx.font='bold 18px Georgia';ctx.textAlign='center';ctx.fillText('CHASE TERRACE PARK',450,80);}
function drawParkWarnings(){if(arenaKey!=='park')return;for(let h of parkSlips){ctx.globalAlpha=h.wait>0?.15:.4;ellipse(h.x,h.y,h.r,h.r*.65,'#c0b284');ctx.globalAlpha=1;}for(let e of enemies)if(e.park&&e.hp>0){if(e.mode==='wind'){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.aim);ctx.fillStyle='#f2c36d55';if(e.move==='pounce'){ctx.restore();radialDraw(e.tx,e.ty,32,'#f5d27d');}else if(e.move==='rush'){ctx.fillRect(0,-18,245,36);ctx.restore();}else{ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,e.kind==='boss'?100:60,-1.25,1.25);ctx.fill();ctx.restore();}}if(e.mode==='collect'){ctx.fillStyle='#244431';ctx.fillRect(e.x-32,e.y-68,64,7);ctx.fillStyle='#a7de9b';ctx.fillRect(e.x-32,e.y-68,64*(1-e.timer/1.6),7);ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText('STOP THE HEAL!',e.x,e.y-74);}}}
function drawParkEnemy(e){ctx.save();ctx.translate(e.x,e.y);if(e.kind==='boss'){let lean=e.wounded?.35:.16;ctx.rotate(lean);ellipse(0,31,21,6,'#203b3055');line([[-4,4],[-8,30]],'#3b3934',7);line([[5,4],[9,30]],'#393831',6);ctx.fillStyle=e.flash>0?'#fff0ca':'#686452';ctx.beginPath();ctx.moveTo(-10,-24);ctx.quadraticCurveTo(6,-33,12,-13);ctx.lineTo(8,13);ctx.lineTo(-11,9);ctx.fill();ellipse(6,-31,8,10,e.flash>0?'#fff0ca':'#b7a283');line([[-1,-37],[6,-43],[13,-36]],'#655849',5);ellipse(10,-30,1,1.5,'#27372e');line([[-7,-12],[14,-2],[27,-13]],'#8b8168',4);ctx.save();ctx.translate(27,-13);ctx.rotate(e.mode==='rush'?1.4:-.4);line([[0,5],[0,-51]],'#b3a98a',3);if(e.mode==='shield'){ctx.fillStyle='#4a5065';ctx.beginPath();ctx.arc(0,-25,36,Math.PI,0);ctx.lineTo(0,-25);ctx.fill();for(let x of [-22,0,22])line([[0,-25],[x,-48]],'#85858b',1);}else line([[-3,-46],[0,-57],[4,-46]],'#4b5060',6);ctx.restore();for(let [x,y] of [[-4,-4],[5,7]])ellipse(x,y,3,3,'#494d3d');}else{let size=e.kind==='bruiser'?1.5:e.kind==='patch'?1.65:1;ctx.scale(size,size);let fur=e.flash>0?'#fff1ce':{scrapper:'#aa8e6c',pouncer:'#717376',bandit:'#795b4d',bruiser:'#5c635e',spitter:'#b49b82',patch:'#867164'}[e.kind]||'#967e65';ellipse(0,15,13,4,'#193c2c55');line([[8,7],[23,5],[22,-9]],fur,5);ellipse(0,4,11,13,fur);ellipse(0,-13,12,11,fur);for(let side of [-1,1]){ctx.fillStyle=fur;ctx.beginPath();ctx.moveTo(side*4,-19);ctx.lineTo(side*11,-30);if(e.kind==='patch'&&side===1){ctx.lineTo(10,-23);ctx.lineTo(7,-25);ctx.lineTo(10,-19);}ctx.lineTo(side*12,-12);ctx.fill();ellipse(side*16,5,4.5,4.5,fur);ellipse(side*4,-13,1.6,2,'#dce8ac');}ellipse(0,-8,2,1,'#75525a');line([[-5,-4],[0,-2],[5,-4]],'#423e38',1);if(e.kind==='bandit'&&e.carry)ellipse(0,9,9,10,'#37473b');if(e.kind==='patch')line([[-8,-20],[-4,-10]],'#d8b99b',2);}ctx.restore();}

// Shared encounter lifecycle: independent of hero dispatch and charm effect processing.
function resetHeroicEncounter(){run.heroicSpawned=false;run.heroicRewarded=false;}
function stepHeroicEncounter(){if(!run.heroicSpawned&&time>=HEROIC_TIME){run.heroicSpawned=true;spawnHeroic();}}
function heroicDefeated(e){if(e.heroic&&!run.heroicRewarded){run.heroicRewarded=true;run.charmPending=true;if(state==='won')openCharmReward();}}
// One heroic wildlife encounter per arena at 60s; never occupies final-boss state.
function spawnHeroic(){let kind={rugby:'charger',chasewater:'fox',sankeys:'courier',quarry:'badger',park:'patch'}[arenaKey];let q=walkable(p.x+210,p.y-140,28);spawn(kind,q);let e=enemies.at(-1);e.heroic=true;e.hp=e.maxHp=300*e.scaleHP;e.r=Math.max(e.r,25);e.speed=62;e.heroMode='hunt';e.heroTimer=2.2;e.damageScale*=1.3;float(p.x,p.y-60,'HEROIC CHALLENGER!','#f3d07d');return e;}
function stepHeroic(e,dt){let dx=p.x-e.x,dy=p.y-e.y,n=Math.hypot(dx,dy)||1,v=e.speed,mx=dx/n,my=dy/n;e.heroTimer-=dt;if(e.stunUntil>time)v=0;else if(e.heroMode==='hunt'&&e.heroTimer<=0){e.heroMode='warn';e.heroTimer=.85;e.hx=mx;e.hy=my;}else if(e.heroMode==='warn'){v=0;if(e.heroTimer<=0){e.heroMode='rush';e.heroTimer=.55;}}else if(e.heroMode==='rush'){v=245;mx=e.hx;my=e.hy;if(e.heroTimer<=0){e.heroMode='rest';e.heroTimer=1.1;}}else if(e.heroMode==='rest'){v=0;if(e.heroTimer<=0){e.heroMode='hunt';e.heroTimer=2.2;}}if(e.slowUntil>time)v*=.7;if(e.charmFrostUntil>time)v*=charmSlowFactor(e);if(e.stagger>0)v*=.2;let q=walkable(e.x+mx*v*dt+e.kx*dt,e.y+my*v*dt,e.r);e.x=q.x;e.y=q.y;e.kx*=Math.exp(-dt*8);e.ky*=Math.exp(-dt*8);if(selected==='jackson'&&p.action==='dodge'&&!p.hitIds.has(e.id)&&dist(p,e)<e.r+p.r+7){p.hitIds.add(e.id);dodgeImpact(e);}if(p.action==='charge'&&!p.hitIds.has(e.id)&&dist(p,e)<e.r+p.r+12){p.hitIds.add(e.id);chargeImpact(e);}if(e.hp>0&&!(e.stunUntil>time)&&dist(p,e)<e.r+p.r&&e.attackCD<=0){hurt(e.heroMode==='rush'?12:8,e);e.attackCD=.85;}}
function drawHeroicWarnings(){for(let e of enemies)if(e.heroic&&e.hp>0&&e.heroMode==='warn'){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(Math.atan2(e.hy,e.hx));ctx.fillStyle='#f3c36c44';ctx.fillRect(0,-24,150,48);line([[0,-24],[150,-24],[150,24],[0,24]],'#f4d38b',2);ctx.restore();}}

// Short resident conversations, changed only by victories in this journey.
const TOWN_CHAT={
 havannah:["I’m not scared. They should be scared of ME!","Told you. Tiny paws, massive attitude."],
 tom:["I’ve seen bigger monsters in the pub on a Friday night!","I’ve seen bigger monsters in the pub on a Friday night!"],
 joseph:["If those monsters think they’re getting past me, they’ve never seen my tackle!","If those monsters think they’re getting past me, they’ve never seen my tackle!"],
 ava:['I wished I could be a cat once… I didn’t mean everyone! You can fix this, can’t you?','You did it! I knew those paws were good for something.'],
 jackson:['Bruce has taken over the rugby club. Fancy helping me get our pitch back?','That’s one down. Reckon we’ve earned a victory lap?'],
 stef:['Right, we’re cats. Brilliant. Give me some essence and I’ll see what I can knock together.','Good work. Bring that essence over—let’s get you ready for the next one.'],
 jodie:['I’m trying to keep everyone together… but the cats keep wandering off. Including me.','You’re giving everyone hope. Just make sure you come back, alright?'],
 evie:['Everyone turned into cats, but the ducks stayed ducks. Suspicious, if you ask me.','The ducks are taking the credit. I’d argue, but there’s quite a few of them.'],
 zak:['Being a cat’s alright. Being trapped in Burntwood forever? Less alright.','That was actually pretty good. Don’t tell anyone I said that.'],
 mimi:['There you are, human. Whiskers suit you. Now let’s work on getting you out of here.','Feel that? The spell’s weakening. Keep going, human.']
};
function residentLine(key){if(key==='joseph'&&selected==='jodie')return 'Mum! Mum! Watch me take this monster down!';return TOWN_CHAT[key][run.visited?.length?1:0];}
function openConversation(key){if(state!=='hub'||!townResidents().some(n=>n.key===key))return false;if(key==='stef')return openWorkshop();state='dialogue';stick.x=stick.y=0;p.vx=p.vy=0;$('townPortrait').src=PORTRAITS[key];$('townPortrait').alt=CHARACTERS[key].name;$('townName').textContent=CHARACTERS[key].name.toUpperCase();$('townLine').textContent=residentLine(key);$('townDialogue').style.display='flex';return true;}
function closeConversation(){if(state!=='dialogue')return;state='hub';$('townDialogue').style.display='none';updateHubHud();}
function drawTalkBubble(x,y){ctx.save();ctx.translate(x+18,y-38);ellipse(0,0,9,7,'#f5e4b9');line([[-5,5],[-7,10],[0,6]],'#f5e4b9',2);for(let dx of [-4,0,4])ellipse(dx,0,1,1,'#34523e');ctx.restore();}

// Stefan's permanent-upgrade shop; available as a self-service shed when playing Stefan.
const WORKSHOP={x:334,y:548,reach:65};
let workshopHero='jackson',pendingPurchase=null;
function workshopNear(){return dist(p,WORKSHOP)<WORKSHOP.reach;}
function openWorkshop(direct=true){if(state!=='hub'||(!direct&&!workshopNear()))return false;state='workshop';workshopHero=selected;pendingPurchase=null;importDraft=null;$('importConfirm').style.display='none';stick.x=stick.y=0;p.vx=p.vy=0;$('workshop').style.display='flex';$('workshopConfirm').style.display='none';$('saveTools').style.display='none';$('workshopGreeting').textContent=selected==='stef'?'Help yourself. You know where everything is.':residentLine('stef');$('workshopIntro').textContent='Final bosses leave 2 essence. Spend it on small permanent upgrades for any character. Heroic enemies leave charms for this run.';if(!progress.workshopSeen){let next={...progress,workshopSeen:true};if(storeProgress(next))progress=next;}renderWorkshop();$('workshopPanel').scrollTop=0;return true;}
function closeWorkshop(){if(state!=='workshop')return;pendingPurchase=null;state='hub';$('workshop').style.display='none';updateHubHud();}
function permanentDescription(key,rank){let n=rank*PERMANENT_UPGRADES[key].step;return (key==='cooldown'?'−':'+')+n+(key==='health'?' health':'%');}
function renderWorkshop(){renderStarters();let hero=workshopHero;$('workshopBalance').textContent=progress.essence+' ESSENCE · SAVED BETWEEN RUNS';$('workshopHeroes').innerHTML=Object.keys(CHARACTER_MODULES).map(key=>'<button data-hero="'+key+'" aria-pressed="'+(key===hero)+'">'+CHARACTERS[key].name+'</button>').join('');for(let b of $('workshopHeroes').querySelectorAll?.('[data-hero]')||[])b.onclick=()=>{pendingPurchase=null;$('workshopConfirm').style.display='none';workshopHero=b.dataset.hero;renderWorkshop();};$('workshopTarget').textContent='PERMANENT UPGRADES · '+CHARACTERS[hero].name.toUpperCase();$('workshopUpgrades').innerHTML=Object.entries(PERMANENT_UPGRADES).map(([key,u])=>{let rank=permanentRank(key,hero),cost=ESSENCE_COSTS[rank];return '<button class="permanentCard" data-permanent="'+key+'" '+(rank>=5||progress.essence<cost?'disabled':'')+'><b>'+u.name+' · '+rank+'/5</b><small>'+u.unit+': '+permanentDescription(key,rank)+(rank<5?' → '+permanentDescription(key,rank+1):' · MAXIMUM')+'</small><span>'+(rank<5?cost+' essence':'COMPLETE')+'</span></button>';}).join('');for(let b of $('workshopUpgrades').querySelectorAll?.('[data-permanent]')||[])b.onclick=()=>requestPermanentPurchase(b.dataset.permanent);$('saveMessage').textContent=saveNotice||'Upgrades apply on your next fresh journey. Keep a backup before changing browser or phone.';}
function requestPermanentPurchase(key){if(state!=='workshop'||!PERMANENT_UPGRADES[key])return false;let rank=permanentRank(key,workshopHero),cost=ESSENCE_COSTS[rank];if(rank>=5||progress.essence<cost)return false;pendingPurchase={hero:workshopHero,key,rank,cost};$('workshopConfirmText').textContent='Upgrade '+CHARACTERS[workshopHero].name+' permanently? '+PERMANENT_UPGRADES[key].name+': '+permanentDescription(key,rank)+' → '+permanentDescription(key,rank+1)+' for '+cost+' essence. Applies next fresh journey.';$('workshopConfirm').style.display='block';$('confirmPermanent').disabled=false;$('workshopConfirm').scrollIntoView?.({block:'nearest'});return true;}
function confirmPermanentPurchase(){if(state!=='workshop'||!pendingPurchase)return false;if(pendingPurchase.kind==='starter'){let item=pendingPurchase;pendingPurchase=null;$('workshopConfirm').style.display='none';return confirmStarterUnlock(item);}let {hero,key,rank,cost}=pendingPurchase;pendingPurchase=null;$('workshopConfirm').style.display='none';if(hero!==workshopHero||permanentRank(key,hero)!==rank||rank>=5||progress.essence<cost)return false;let next=JSON.parse(JSON.stringify(progress));next.essence-=cost;next.heroes[hero]=next.heroes[hero]||{};next.heroes[hero][key]=rank+1;if(!storeProgress(next)){renderWorkshop();return false;}progress=next;renderWorkshop();return true;}
function cancelPermanentPurchase(){pendingPurchase=null;$('workshopConfirm').style.display='none';}
function showSaveTools(){if(state!=='workshop')return;$('saveTools').style.display='block';$('saveBackup').value=exportProgress();$('saveMessage').textContent=saveNotice||'Copy all this text somewhere safe. Restoring replaces saved essence and upgrades; it does not add them together.';}

// Town-only presentation. Reuses approved hero renderers without running combat AI.
const TOWN_RESIDENTS=[
 {key:'havannah',x:630,y:505,place:'Town garden'},
 {key:'tom',x:677,y:590,place:'Town green'},
 {key:'joseph',x:540,y:827,place:'Rugby Club'},
 {key:'jackson',x:365,y:816,place:'Rugby Club'},
 {key:'ava',x:490,y:571,place:'Town garden'},
 {key:'stef',x:334,y:548,place:'Workshop corner'},
 {key:'jodie',x:222,y:549,place:'Cottage lane'},
 {key:'evie',x:278,y:831,place:'Chasewater path'},
 {key:'zak',x:615,y:296,place:'Sankey’s Corner'}
];
function townResidents(){let shop=shopkeeperKey();return TOWN_RESIDENTS.filter(n=>n.key!==selected&&n.key!==shop);}
// Shared visual sizing lives in the character renderers, identical in town and combat.
const TOWN_DRAW_SCALE={havannah:1,tom:1,joseph:1,jackson:1,ava:1,stef:1,jodie:1,evie:1,zak:1,mimi:1};
function drawTownHero(key,x,y,phase=0){let player=p,hero=selected;ctx.save();try{ctx.translate(x,y);let size=TOWN_DRAW_SCALE[key]||1;ctx.scale(size,size);if(key==='havannah'){drawHavannahBody(0,0,phase,{dir:{x:0,y:1}});return;}if(key==='tom'){drawTomBody(0,0,phase,{dir:{x:0,y:1}});return;}if(key==='joseph'){drawJosephBody(0,0,phase,{dir:{x:0,y:1}});return;}if(key==='mimi'){drawMimiBody(0,Math.sin(phase*2),1,0,0);return;}p={x:0,y:0,vx:0,vy:0,r:14,walk:phase,inv:0,throwT:0,action:null,actionT:0,dir:{x:0,y:1},swing:null,claws:null,frenzy:0,kittenCall:0};selected=key;CHARACTER_MODULES[key].draw();}finally{p=player;selected=hero;ctx.restore();}}
function drawHubPlayer(){ctx.save();ctx.translate(p.x,p.y);let size=TOWN_DRAW_SCALE[selected]||1;ctx.scale(size,size);ctx.translate(-p.x,-p.y);CHARACTER_MODULES[selected].draw();ctx.restore();}
function townName(x,y,name,color='#fff0bd'){ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillStyle='#173c2dcc';ctx.fillRect(x-39,y-57,78,17);ctx.fillStyle=color;ctx.fillText(name,x,y-45);}
function drawTownResidents(){for(let n of townResidents()){drawTownHero(n.key,n.x,n.y,hub.time*.5+n.x);townName(n.x,n.y,CHARACTERS[n.key].name);drawTalkBubble(n.x,n.y);if(n.key==='jackson'){ballArt(n.x+22,n.y+17-Math.abs(Math.sin(hub.time*2))*9,5,hub.time,false);}if(n.key==='ava')starArt(n.x+24,n.y-18+Math.sin(hub.time*2)*4,4,hub.time);if(n.key==='evie')drawDuck({x:n.x+22,y:n.y+10,r:6,mode:'ally',age:hub.time,t:0});}}
function townBossPreview(g){return {id:-1,kind:'boss',x:g.x,y:g.y,r:42,hp:1,maxHp:1,age:run.visited?.includes(g.key)?0:hub.time,flash:0,stunUntil:0,slowUntil:0,wounded:!!run.visited?.includes(g.key),mode:'walk',park:g.key==='park',move:'umbrella',market:g.key==='sankeys',chase:g.key==='chasewater',quarry:g.key==='quarry'};}
function drawTownBosses(){for(let g of hub.portals){let done=run.visited?.includes(g.key);ctx.save();if(done){ctx.translate(g.x,g.y+15);ctx.rotate(.22);ctx.scale(1,.72);ctx.translate(-g.x,-g.y);}drawEnemy(townBossPreview(g));if(done){ // Gentle cartoon bandage, bruise and dizzy stars: still the same boss.
 ctx.fillStyle='#f0e2bf';ctx.fillRect(g.x-13,g.y-32,26,7);line([[g.x-4,g.y-32],[g.x-1,g.y-25]],'#b9a782',2);ellipse(g.x+14,g.y-14,5,3,'#927b9a');
}ctx.restore();if(done){starArt(g.x-21,g.y-59,4,hub.time);starArt(g.x+20,g.y-63,3,-hub.time);line([[g.x+49,g.y+24],[g.x+49,g.y-10]],'#6c5840',2);ctx.fillStyle='#d9e6aa';ctx.fillRect(g.x+49,g.y-10,21,13);line([[g.x+53,g.y-4],[g.x+57,g.y],[g.x+65,g.y-7]],'#4c7652',2);}townName(g.x,g.y-24,ARENAS[g.key].bossShort.toUpperCase(),done?'#dce8c2':'#f8d491');ctx.fillStyle='#f9e7b6';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText(done?'DEFEATED · RESTING':hub.finished?'NEXT RUN':'TAP TO CHALLENGE',g.x,g.y+55);}}
function hubTap(worldX,worldY){if(state!=='hub')return false;let point={x:worldX,y:worldY};if(dist(point,SHOPKEEPER)<38||dist(point,hub.shop)<38)return interactShopkeeper(true);if(dist(point,WORKSHOP)<42)return openWorkshop();let resident=townResidents().find(n=>dist(point,n)<28);if(resident)return openConversation(resident.key);let g=hub.portals.find(g=>dist(point,g)<58);if(g&&!run.visited?.includes(g.key))return enterArena(g.key);return false;}
function hubScreenPoint(x,y){let box=canvas.getBoundingClientRect();return {x:cam.x+(x-box.left-W/2)/scale,y:cam.y+(y-box.top-H*.47)/scale};}
let hubPointer=null;
function beginHubPointer(e){if(state!=='hub'||e.isPrimary===false)return;hubPointer={id:e.pointerId,x:e.clientX,y:e.clientY};}
function endHubPointer(e){let start=hubPointer;hubPointer=null;if(!start||start.id!==e.pointerId||state!=='hub'||Math.hypot(e.clientX-start.x,e.clientY-start.y)>12)return;let q=hubScreenPoint(e.clientX,e.clientY);hubTap(q.x,q.y);}

// Fresh stock has distinct choices and, when affordable, at least one usable purchase.
function rollShopStock(){let keys=[];for(let n=0;keys.length<3&&n<60;n++){let key=rollCharmKey();if(!keys.includes(key))keys.push(key);}for(let key of Object.keys(CHARMS))if(key!=='purse'&&!keys.includes(key)&&keys.length<3)keys.push(key);let affordable=Object.keys(CHARMS).filter(k=>k!=='purse'&&CHARM_GOLD_PRICES[CHARMS[k].rarity]<=hub.coins);if(affordable.length&&!keys.some(k=>affordable.includes(k))){let pool=affordable.filter(k=>!keys.includes(k));keys[2]=pool[Math.min(pool.length-1,Math.floor(rewardRandom()*pool.length))];}return keys.map(key=>({key,bought:false}));}
// Run gold / shop stock and saved starter unlocks. Essence debits commit before effects.
let goldDrops=[],inventoryResume=null,rerollPending=null,starterFilter=0;
function grantGold(n){hub.coins+=n;run.goldEarned=(run.goldEarned||0)+n;}
function dropGold(e){if(e===boss){grantGold(35);return;}if(e.heroic){grantGold(20);return;}if(rand()<.18)goldDrops.push({x:e.x,y:e.y,value:2});if(goldDrops.length>80)goldDrops.shift();}
function stepGold(dt){let reach=90*(1+buildStats().pickup/100);for(let i=goldDrops.length-1;i>=0;i--){let g=goldDrops[i],d=dist(p,g)||1;if(d<reach){let step=Math.min(d,(170+reach-d)*dt);g.x+=(p.x-g.x)/d*step;g.y+=(p.y-g.y)/d*step;}if(d<19){grantGold(g.value);goldDrops.splice(i,1);}}}
function drawGold(){for(let g of goldDrops){ellipse(g.x,g.y,5,5,'#edc65f');ellipse(g.x-1,g.y-1,2,2,'#fff1ba');}}
function applyStarter(){let key=progress.starter;if(key&&progress.starterUnlocks.includes(key)&&CHARMS[key]){gainCharm(key);run.startingCharm=key;if(key==='purse'&&!run.purseGranted){grantGold(100);run.purseGranted=true;}}}
function ensureShopStock(force=false){let stage=run.visited?.length||0;if(force||!run.shopStock||run.shopStockStage!==stage){run.shopStockStage=stage;run.shopStock=rollShopStock();run.shopGeneration=(run.shopGeneration||0)+1;}}
function renderCharmStock(){ensureShopStock();$('shopCharmStock').innerHTML='<h3>CHARMS · RUN GOLD</h3>'+run.shopStock.map((s,i)=>'<button class="shopItem rarityItem" style="--rarity:'+CHARMS[s.key].color+'" data-stock="'+i+'" '+(s.bought||hub.finished||hub.coins<CHARM_GOLD_PRICES[CHARMS[s.key].rarity]?'disabled':'')+'><span>'+RARITIES[CHARMS[s.key].rarity].name.toUpperCase()+'</span><b>'+CHARMS[s.key].icon+' '+CHARMS[s.key].name+'</b><small>'+charmDetail({key:s.key,rank:1})+'</small><span>'+CHARM_GOLD_PRICES[CHARMS[s.key].rarity]+' gold'+(s.bought?' · SOLD':'')+'</span></button>').join('');for(let b of $('shopCharmStock').querySelectorAll?.('[data-stock]')||[])b.onclick=()=>buyCharm(+b.dataset.stock);$('shopReroll').textContent='REROLL CHARMS · '+(2+2*(run.shopRerolls||0))+' ESSENCE';$('shopReroll').disabled=hub.finished||progress.essence<2+2*(run.shopRerolls||0);}
function buyCharm(index){if(state!=='shop'||hub.finished)return false;let offer=run.shopStock?.[index];if(!offer||offer.bought)return false;let cost=CHARM_GOLD_PRICES[CHARMS[offer.key].rarity];if(hub.coins<cost)return false;offer.bought=true;hub.coins-=cost;gainCharm(offer.key);renderHubShop();return true;}
function requestShopReroll(){if(state!=='shop'||hub.finished)return false;let cost=2+2*(run.shopRerolls||0);if(progress.essence<cost)return false;rerollPending={cost,generation:run.shopGeneration};$('rerollConfirmText').textContent='Spend '+cost+' saved essence to replace the remaining charm offers? Purchased charms stay yours. Next reroll costs '+(cost+2)+'.';$('rerollConfirm').style.display='block';$('rerollConfirm').scrollIntoView?.({block:'nearest'});return true;}
function confirmShopReroll(){let pending=rerollPending;rerollPending=null;$('rerollConfirm').style.display='none';if(state!=='shop'||hub.finished||!pending||pending.generation!==run.shopGeneration||pending.cost!==2+2*(run.shopRerolls||0)||progress.essence<pending.cost)return false;let next=JSON.parse(JSON.stringify(progress));next.essence-=pending.cost;if(!storeProgress(next))return false;progress=next;run.shopRerolls=(run.shopRerolls||0)+1;ensureShopStock(true);renderHubShop();return true;}
function renderStarters(){let chosen=progress.starter;$('starterSelection').textContent='NEXT FRESH RUN: '+(chosen?CHARMS[chosen].name:'No starting charm')+' · one equipped slot';$('starterList').innerHTML=Object.entries(CHARMS).filter(([k,c])=>c.rarity===starterFilter).map(([key,c])=>{let owned=progress.starterUnlocks.includes(key),cost=STARTER_COSTS[c.rarity];return '<button class="permanentCard rarityItem" style="--rarity:'+c.color+'" data-starter="'+key+'" '+((!owned&&progress.essence<cost)||chosen===key?'disabled':'')+'><b>'+c.icon+' '+c.name+'</b><small>'+RARITIES[c.rarity].name+' · '+c.text+'</small><span>'+(owned?chosen===key?'SELECTED':'SELECT FOR NEXT RUN':cost+' essence · permanent unlock')+'</span></button>';}).join('');for(let b of $('starterList').querySelectorAll?.('[data-starter]')||[])b.onclick=()=>progress.starterUnlocks.includes(b.dataset.starter)?selectStarter(b.dataset.starter):requestStarterUnlock(b.dataset.starter);}
function requestStarterUnlock(key){if(state!=='workshop'||!CHARMS[key]||progress.starterUnlocks.includes(key)||progress.essence<STARTER_COSTS[CHARMS[key].rarity])return false;pendingPurchase={kind:'starter',key,cost:STARTER_COSTS[CHARMS[key].rarity]};$('workshopConfirmText').textContent='Permanently unlock '+CHARMS[key].name+' as a starting option for '+pendingPurchase.cost+' essence? Select it afterwards; one starting charm per fresh run.';$('workshopConfirm').style.display='block';$('workshopConfirm').scrollIntoView?.({block:'nearest'});return true;}
function confirmStarterUnlock(pending){if(state!=='workshop'||progress.starterUnlocks.includes(pending.key)||progress.essence<pending.cost)return false;let next=JSON.parse(JSON.stringify(progress));next.essence-=pending.cost;next.starterUnlocks.push(pending.key);if(!storeProgress(next))return false;progress=next;renderWorkshop();return true;}
function selectStarter(key){if(state!=='workshop'||(key!==null&&!progress.starterUnlocks.includes(key)))return false;let next={...progress,starter:key};if(!storeProgress(next))return false;progress=next;renderStarters();return true;}
function openInventory(){if(!['playing','hub'].includes(state))return false;inventoryResume=state;state='inventory';stick.x=stick.y=0;$('inventory').style.display='flex';renderInventory();$('inventoryPanel').scrollTop=0;return true;}
function closeInventory(){if(state!=='inventory')return;state=inventoryResume;inventoryResume=null;$('inventory').style.display='none';if(state==='hub')updateHubHud();else updateHud();}
function inventoryAction(action,a,b){if(state!=='inventory'||inventoryResume!=='hub'||hub.finished)return false;state='shop';let ok=action==='fuse'?fuseCharm():equipCharm(a,b);state='inventory';renderInventory();return ok;}
function renderInventory(){let s=buildStats(),st=stats();$('inventoryTitle').textContent=CHARACTERS[selected].name.toUpperCase()+' · BUILD';$('inventoryEquipment').innerHTML=run.charms.map(c=>'<article class="inventoryCharm rarityItem" style="--rarity:'+CHARMS[c.key].color+'"><b>'+charmCaption(c)+'</b><p>'+charmDetail(c)+'</p></article>').join('')||'<p>No charms equipped. Defeat a heroic enemy or visit Mimi.</p>';$('inventoryWarnings').textContent=charmRank('blunt')?'BLUNT PROMISE: critical chance, critical damage and Patient Fang are disabled.':run.charmFX?.lanternUsed?'LAST LIGHT USED: healing is disabled until the next arena.':charmRank('patient')&&charmRank('keen')?'Patient Fang resets on any critical: extra critical chance reduces how often its guarantee triggers.':'';
let values={health:st.hp.toFixed(0),armour:s.armour.toFixed(1),regen:s.regen.toFixed(2)+' HP/s',power:'+'+s.power.toFixed(1)+'%',tempo:s.tempo.toFixed(1)+'%',precision:s.critChance.toFixed(1)+'%',ferocity:s.critDamage.toFixed(0)+'%',agility:st.speed.toFixed(0)+' speed',reflexes:dodgeCooldown().toFixed(2)+'s dodge',focus:specialCooldown().toFixed(2)+'s special',scavenging:'+'+s.pickup.toFixed(0)+'%',restoration:(Math.round((healingFactor()-1)*100))+'%'};
$('inventoryStats').innerHTML=Object.entries(STAT_TRACKS).map(([key,d])=>'<div><b>'+d.name+' · '+values[key]+'</b><small>Chosen: '+statValue(key).toFixed(2)+d.unit+' · Levels: '+growthValue(key).toFixed(2)+d.unit+(key==='health'?' · Permanent: +'+activePermanentBonus('health'):key==='power'?' · Permanent: +'+activePermanentBonus('damage')+'%':key==='agility'?' · Permanent: +'+activePermanentBonus('speed')+'%':key==='focus'?' · Permanent: −'+activePermanentBonus('cooldown')+'%':key==='restoration'?' · Permanent: +'+activePermanentBonus('healing')+'%':'')+'</small></div>').join('');$('inventoryBag').innerHTML='<h3>SPARES · '+run.charmBag.length+'</h3>'+run.charmBag.map((c,i)=>'<article class="inventoryCharm rarityItem" style="--rarity:'+CHARMS[c.key].color+'"><b>'+charmCaption(c)+'</b><p>'+charmDetail(c)+'</p>'+((inventoryResume==='hub'&&!hub.finished&&!charmRank(c.key))?(run.charms.length<3?'<button data-bag="'+i+'" data-slot="-1">EQUIP</button>':run.charms.map((old,slot)=>'<button data-bag="'+i+'" data-slot="'+slot+'">REPLACE '+CHARMS[old.key].name+'</button>').join('')):'')+'</article>').join('');for(let b of $('inventoryBag').querySelectorAll?.('[data-bag]')||[])b.onclick=()=>inventoryAction('equip',+b.dataset.bag,+b.dataset.slot);$('inventoryFuse').disabled=inventoryResume!=='hub'||hub.finished||!fusionPair();$('inventoryNote').textContent=inventoryResume==='playing'?'Combat paused. Inspect freely; equipment changes and fusion are available in town.':'Permanent upgrades and charms are included in totals. Temporary shrine bonuses are labelled in the combat HUD.';}

// Shared dispatch: the engine never changes arena balance to fix one character.
const CHARACTER_MODULES={
 havannah:{interval:()=>.55/(tier>=2?1.2:1),attack:havAttack,draw:drawHavannah,special:havSpecial,dodge:havDodge,update:updateHavannah,motion:havMotion,avoidHit:havAvoidHit,goal:havGoal},
 tom:{interval:()=>.9/(tier>=4?1.2:1),attack:tomAttack,draw:drawTom,special:tomSpecial,dodge:tomDodge,update:updateTom,motion:tomMotion,avoidHit:tomAvoidHit,enemyDraw:drawTomEnemy},
 joseph:{interval:()=>.29/(tier>=1?1.15:1),attack:josephAttack,draw:drawJoseph,special:josephSpecial,dodge:josephDodge,update:updateJoseph,motion:josephMotion,avoidHit:josephAvoidHit},
 mimi:{interval:()=>tier>=2?.44:.62,attack:mimiAttack,draw:drawMimi,special:mimiSpecial,dodge:mimiDodge,update:updateMimi},
 jackson:{attack:shoot,draw:drawRugbyHero,special:jacksonCharge,dodge:quickDodge,update(){}},
 ava:{attack:shoot,draw:drawRugbyHero,special:avaSpecial,dodge:quickDodge,update(){}},
 stef:{interval:()=>tier>=4?.76:tier>=2?.45:.60,attack:startSweep,draw:drawStef,special:byOrder,dodge:push,update:updateStef},
 jodie:{attack:startClaws,draw:drawJodie,special:kittenChaos,dodge:quickDodge,update:updateCats},
 evie:{attack:queueDucks,draw:drawEvie,special:ducksAssemble,dodge:quickDodge,update:updateDucks},
 zak:{attack:zakGasBlast,draw:drawZak,special:zakExplosion,dodge:zakDodge,update:updateZak}
};
const ARENA_MODULES={
 rugby:{wave:rugbyWave,spawn:spawnRugby,ground:drawRugbyGround},
 chasewater:{wave:chaseWave,spawn:spawnRugby,ground:drawChasewater},
 sankeys:{wave:sankeyWave,spawn:spawnMarket,ground:drawSankeys},
 park:{wave:parkWave,spawn:spawnPark,ground:drawParkGround},
 quarry:{wave:quarryWave,spawn:spawnQuarry,ground:drawQuarry}
};
function spawn(kind,at){ARENA_MODULES[arenaKey].spawn(kind,at);}
function ground(){ARENA_MODULES[arenaKey].ground();}
function rugbyWave(){let pt=pressureTime(),roll=rand(),kind=pt>10&&roll<.19?'charger':pt>20&&roll>.83?'heavy':'swarm';spawn(kind);if(pt>20&&rand()<.45){spawn('swarm');spawn('swarm');}nextSpawn=stageSpawnDelay(Math.max(.42,.88-time*.0018));}

function normalAttack(){let f=run.charmFX,old=f?{attacks:f.attacks,echo:f.echo}:null;charmAttackStarted();let ok=CHARACTER_MODULES[selected].attack();if(!ok&&old){f.attacks=old.attacks;f.echo=old.echo;}return ok;}

function normalAttackInterval(){return (CHARACTER_MODULES[selected].interval?.()??CHARACTERS[selected].rate)*normalRate();}

function charge(){let before=p?.chargeCD||0;CHARACTER_MODULES[selected].special();if(p?.chargeCD>before)charmSpecialUsed();}
function dodge(){if(state==='hub')return;CHARACTER_MODULES[selected].dodge();}

$('pickHavannah').onclick=()=>selectCharacter('havannah');addEventListener('pointerdown',havWakeSound);
$('pickTom').onclick=()=>selectCharacter('tom');addEventListener('pointerdown',tomWakeSound,{once:true});
$('pickJoseph').onclick=()=>selectCharacter('joseph');addEventListener('pointerdown',josephWakeSound,{once:true});
$('inventoryButton').onclick=openInventory;$('inventoryClose').onclick=closeInventory;$('inventoryFuse').onclick=()=>inventoryAction('fuse');$('shopReroll').onclick=requestShopReroll;$('confirmReroll').onclick=confirmShopReroll;$('cancelReroll').onclick=()=>{rerollPending=null;$('rerollConfirm').style.display='none';};$('starterRarity').onchange=()=>{starterFilter=+$('starterRarity').value;renderStarters();};$('starterNone').onclick=()=>selectStarter(null);$('pickPark').onclick=()=>selectArena('park');
// Pointer controls already handle movement/actions. Cancel native touch zoom separately,
// forwarding exactly one click for ordinary menu/upgrade buttons.
const tapStarts=new Map();
addEventListener('touchstart',e=>{for(let t of Array.from(e.changedTouches||[]))tapStarts.set(t.identifier,{x:t.clientX,y:t.clientY,button:t.target?.closest?.('button')});if(e.touches?.length>1&&state!=='menu')e.preventDefault();},{passive:false});
addEventListener('touchend',e=>{let target=e.target,button=target?.closest?.('button'),gameplay=target?.closest?.('#game,#controls,#hud');if(button||gameplay){if(e.cancelable)e.preventDefault();if(button&&button.id!=='charge'&&button.id!=='dodge'&&!button.disabled){let t=e.changedTouches?.[0],start=t&&tapStarts.get(t.identifier);if(start&&start.button===button&&Math.hypot(t.clientX-start.x,t.clientY-start.y)<14)button.click();}}for(let t of Array.from(e.changedTouches||[]))tapStarts.delete(t.identifier);},{passive:false});
addEventListener('touchcancel',e=>{for(let t of Array.from(e.changedTouches||[]))tapStarts.delete(t.identifier);},{passive:true});
addEventListener('dblclick',e=>{if(e.target?.closest?.('#game,#controls,#menu,#panel'))e.preventDefault();},{passive:false});
addEventListener('gesturestart',e=>{if(state!=='menu')e.preventDefault();},{passive:false});


canvas.onpointerdown=beginHubPointer;canvas.onpointerup=endHubPointer;canvas.onpointercancel=()=>{hubPointer=null;};
$('newJourney').onclick=startJourney;$('townClose').onclick=closeConversation;$('workshopClose').onclick=closeWorkshop;$('confirmPermanent').onclick=confirmPermanentPurchase;$('cancelPermanent').onclick=cancelPermanentPurchase;$('saveOptions').onclick=showSaveTools;$('copySave').onclick=async()=>{try{await navigator.clipboard.writeText(exportProgress());$('saveMessage').textContent='Backup copied. Keep it somewhere safe.';}catch(e){$('saveBackup').value=exportProgress();$('saveBackup').focus();$('saveBackup').select();$('saveMessage').textContent='Select and copy the backup text.';}};let importDraft=null;$('prepareImport').onclick=()=>{importDraft=$('saveBackup').value;$('importConfirm').style.display='block';$('importConfirm').scrollIntoView?.({block:'nearest'});};$('cancelImport').onclick=()=>{importDraft=null;$('importConfirm').style.display='none';};$('confirmImport').onclick=()=>{if(importDraft!==null)importProgress(importDraft);importDraft=null;$('importConfirm').style.display='none';};
